(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0013.js"] = [{"id":"poem-56e9eeb67ed874bb776f07df","title":"再会夏石芝","author":"宋伯仁","dynasty":"宋","verses":["自与君相别，骎骎已数年。","一缄书不寄，千里梦徒然。","雨店花新长，风櫺月几圆。","岭梅无恙否，愁满鬓丝边。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-f9338e03-2b4f-4bf8-9ab0-4c7fd65cccff","tags":[]},{"id":"poem-56f2fa3db880c0a2e120a991","title":"谢新恩·樱花落尽阶前月","author":"李煜","dynasty":"五代","verses":["樱花落尽阶前月，象床愁倚薰笼。","远似去年今日，恨还同。","双鬟不整云憔翠，泪沾红抹胸。","何处相思苦？纱窗醉梦中。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-31","tags":[]},{"id":"poem-56f311bb7f7a5533778b9713","title":"晨诣超师院读禅经","author":"柳宗元","dynasty":"唐","verses":["汲井漱寒齿，清心拂尘服。","闲持贝叶书，步出东斋读。","真源了无取，妄迹世所逐。","遗言冀可冥，缮性何由熟。","道人庭宇静，苔色连深竹。","日出雾露余，青松如膏沐。","澹然离言说，悟悦心自足。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-2954ddd2-f1c7-41b1-8c9e-42058398cde0","tags":["唐诗三百首","五言古诗","抒情","贬谪"]},{"id":"poem-56f742205d624b0adff18044","title":"喜王六同宿","author":"张籍","dynasty":"唐","verses":["十八年来恨别离，唯同一宿咏新诗。","更相借问诗中语，共说如今胜旧时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-58a7e4bd-15de-4126-a91c-de9562694ce8","tags":[]},{"id":"poem-57010264a25dded015734405","title":"遐方怨·帘影细","author":"顾敻","dynasty":"五代","verses":["帘影细，簟纹平。","象纱笼玉指，缕金罗扇轻。","嫩双脸似花明，两条眉黛远山横。","风箫歇，镜尘生。","辽塞音书绝，梦魂长暗惊。","玉郎经岁负娉婷，教人怎不恨无情。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-16","tags":[]},{"id":"poem-570ae34e9370ee588964c59d","title":"和公廙喜雪","author":"司马光","dynasty":"宋","verses":["向来河洛久愆阳，祷祀徒劳罄肃庄。","林雪飞花欣暂白，麦田濡叶未全黄。","城中稍觉桑薪贵，村外时闻社瓮香。","八使孜孜悯惸独，斯民那复畏凶荒。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-5f61c379-0444-450c-8524-89594072bcc7","tags":[]},{"id":"poem-570df6ae86d776398bea9c7e","title":"咏田家","author":"聂夷中","dynasty":"唐","verses":["二月卖新丝，五月粜新谷。","医得眼前疮，剜却心头肉。","我愿君王心，化作光明烛。","不照绮罗筵，只照逃亡屋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-0eea5bcf-1f67-4a9f-b70f-d60dcea99111","tags":[]},{"id":"poem-571166c669aa55478acfa691","title":"晨风","author":"佚名","dynasty":"先秦","verses":["𫛣彼晨风，郁彼北林。未见君子，忧心钦钦。如何如何，忘我实多！","山有苞栎，隰有六駮。未见君子，忧心靡乐。如何如何，忘我实多！","山有苞棣，隰有树檖。未见君子，忧心如醉。如何如何，忘我实多！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-131","tags":[]},{"id":"poem-571351bc56d0978978d633a6","title":"杨柳枝寿杯词十八首 二","author":"司空图","dynasty":"唐","verses":["撼晚梳空不自持，与君同折上楼时。","春风还有常情处，系得人心免别离。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-991b7a35-43c0-43cc-9695-e99329ecdf08","tags":[]},{"id":"poem-5718dadd6a14cc5d68694ccf","title":"题武关","author":"李涉","dynasty":"唐","verses":["来往悲欢万里心，多从此路计浮沈。","皆缘不得空门要，舜葬苍梧直至今。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-eee8425b-6325-4e66-a22b-13b7979564cc","tags":[]},{"id":"poem-57305e035d61c6ad6b795a18","title":"斯干","author":"佚名","dynasty":"先秦","verses":["秩秩斯干，幽幽南山。如竹苞矣，如松茂矣。兄及弟矣，式相好矣，无相犹矣。","似续妣祖，筑室百堵，西南其户。爰居爰处，爰笑爰语。","约之阁阁，椓之橐橐。风雨攸除，鸟鼠攸去，君子攸芋。","如跂斯翼，如矢斯棘，如鸟斯革，如翚斯飞，君子攸跻。","殖殖其庭，有觉其楹。哙哙其正，哕哕其冥。君子攸宁。","下莞上簟，乃安斯寝。乃寝乃兴，乃占我梦。吉梦维何？维熊维罴，维虺维蛇。","大人占之：维熊维罴，男子之祥；维虺维蛇，女子之祥。","乃生男子，载寝之床。载衣之裳，载弄之璋。其泣喤喤，朱芾斯皇，室家君王。","乃生女子，载寝之地。载衣之裼，载弄之瓦。无非无仪，唯酒食是议，无父母诒罹。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-188","tags":[]},{"id":"poem-5731c26204a764af3ce41f89","title":"秋日登郡楼望赞皇山感而成咏","author":"李德裕","dynasty":"唐","verses":["昔人怀井邑，为有挂冠期。","顾我飘蓬者，长随泛梗移。","越吟因病感，潘鬓入秋悲。","北指邯郸道，应无归去期。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-4cd6914d-7644-4e9e-b758-09def40c83c0","tags":[]},{"id":"poem-573913bd5d6f762afd018624","title":"贝母","author":"张载","dynasty":"宋","verses":["贝母阶前蔓百寻，双桐盘绕叶森森。","刚强顾我蹉跎甚，时欲低柔警寸心。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-bf2b46e0-f93c-4e7a-b7ac-f47ac0e86ed7","tags":[]},{"id":"poem-5741ab8cbaef63aac1505639","title":"从幸香山寺应制","author":"沈佺期","dynasty":"唐","verses":["南山奕奕通丹禁，北阙峨峨连翠云。","岭上楼台千地起，城中钟鼓四天闻。","旃檀晓阁金舆度，鹦鹉晴林采眊分。","愿以醍醐参圣酒，还将[衹]苑当秋汾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-18a656df-00f4-4000-b36e-2d0e490fbb99","tags":[]},{"id":"poem-5742845a614058679df71706","title":"送永阳崔明府","author":"司空曙","dynasty":"唐","verses":["古国群舒地，前当桐柏关。","连绵江上雨，稠叠楚南山。","沙馆行帆息，枫洲候吏还。","乘篮若有暇，精舍在林间。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-07c96e92-8589-4e1b-9c90-44feedbaca48","tags":[]},{"id":"poem-574b44947a66faaefded4058","title":"正月十五日夜应制","author":"孙逖","dynasty":"唐","verses":["洛城三五夜，天子万年春。","彩仗移双阙，琼筵会九宾。","舞成苍颉字，灯作法王轮。","不觉东方日，遥垂御藻新。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-1541ca51-f544-437b-bb53-0d55627ab52d","tags":[]},{"id":"poem-57550978b866f52487a50ae6","title":"琵琶仙・自度曲·双桨来时","author":"姜夔","dynasty":"宋","verses":["双桨来时，有人似、旧曲桃根桃叶。","歌扇轻约飞花，蛾眉正奇绝。","春渐远、汀洲自绿，更添了、几声啼。","十里扬州，三生杜牧，前事休说。","又还是、宫烛分烟，奈愁里、匆匆换时节。","都把一襟芳思，与空阶榆荚。","千万缕、藏鸦细柳，为玉尊、起舞回雪。","想见西出阳关，故人初别。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-130","tags":["宋词三百首"]},{"id":"poem-5759e7357e9f32a13f24e920","title":"武肃王有旨石桥设斋会进一诗 六","author":"延寿","dynasty":"唐","verses":["登云步岭涉烟程，好景随心次第生。","圣者已符祥瑞事，地灵全副祷祈情。","洞深重叠拖云湿，滩浅潺湲漱水清。","愿满事圆归去路，便风相送片帆轻。","（见《四库全书珍本初集》本宋林表民《天台前集别编》。","（按：《全唐诗》卷八五一收六诗，仅云为「吴越僧」作。","今确定为吴越释延寿作。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-0bb514ee-0de7-4847-bd46-1a7a353fe286","tags":[]},{"id":"poem-57643095201f3bedf17fc103","title":"岘山送崔子向之宣州谒裴使君","author":"皎然","dynasty":"唐","verses":["楚思入诗清，晨登岘山情。","秋天水西寺，古木宛陵城。","琴匣应将往，书车亦共行。","吾知江太守，一顾重君名。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-019a61c7-f187-40a0-b282-fe86c6c98531","tags":[]},{"id":"poem-576449fe68b81879ddd4f94e","title":"凌云峰","author":"释延寿","dynasty":"宋","verses":["烟萝高𪩘势凌云，影泻斜阳出海门。","曾与支公探隠去，夜寒雷雨上方闻。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-dc0aacf6-3e95-4aae-b386-92b3e1cae59e","tags":[]},{"id":"poem-5766cf25001976d7269324cf","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["虽然如此，伊家富贵，那更青春年少。","看你紫袍着体，金带垂腰。","做你的媳妇呵，应须有封号，金花紫诰。","必俊倬，须媚娇。","若还他丑貌，相公，怎不相休去了？(生唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5224","tags":[]},{"id":"poem-57675d9145fa0157747bd11c","title":"五祖再来赞","author":"释了惠","dynasty":"宋","verses":["前身后身，坐底立底。","半假半真，全非全是。","只因擡手肆乖张，万古黄梅如鼎沸。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-ff0cf062-7154-483d-b1ca-2b93a2fa8c18","tags":[]},{"id":"poem-577925918cc32a05b6e6b0b9","title":"省题诗二十一首 咏菊","author":"王棨","dynasty":"唐","verses":["秋来多野菊，节应[有]黄花。","闲叶玉如栗，满藂金出沙。","池边迷瑞鹄，洞里悟仙牙。","蘂散非红豓，香飘异[绮]葩。","赠诗宜魏帝，泛酒称陶家。","明日登高处，期君手不赊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-b659cc66-8238-432b-b46c-0616e66d342d","tags":[]},{"id":"poem-577dcb4566d3b3c1e976381a","title":"南阳酂诗","author":"王祜","dynasty":"宋","verses":["置酒向南宫，分明将将雄。","指踪为第一，大国赏元戎。","似续惟人杰，危忘尽狗功。","贤哉垂俭德，千古仰清风。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-fd1b7735-40a2-41b7-bae0-9d31e4b1ba2d","tags":[]},{"id":"poem-57831c6f41d225c5bdc142f6","title":"汴河曲","author":"李益","dynasty":"唐","verses":["汴水东流无限春，隋家宫阙已成尘。","行人莫上长堤望，风起杨花愁杀人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-1ba500f4-7cd5-4e87-91e0-b23ec74228e1","tags":[]},{"id":"poem-5786eb6e3d8210a78266b6c4","title":"芣苡","author":"佚名","dynasty":"先秦","verses":["采采芣苡，薄言采之。采采芣苡，薄言有之。","采采芣苡，薄言掇之。采采芣苡，薄言捋之。","采采芣苡，薄言袺之。采采芣苡，薄言襭之。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-7","tags":[]},{"id":"poem-578d7bca83edfb0ad2ca31e8","title":"客舍书情寄赵中丞","author":"崔峒","dynasty":"唐","verses":["东楚复西秦，浮云类此身。","关山劳策蹇，僮仆惯投人。","孤客来千里，全家托四邻。","生涯难自料，中夜问[情亲]。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-039c2a5b-73bc-47b4-a6dd-68cb46a8dc59","tags":[]},{"id":"poem-57901a869afcc8ce4c9e8c8a","title":"偶然作六首 四","author":"王维","dynasty":"唐","verses":["陶潜任天真，其性颇躭酒。","自从弃官来，家贫不能有。","九月九日时，菊花空满手。","中心窃自思，傥有人送否。","白衣携壶觞，果来遗老叟。","且喜得斟酌，安问升与斗。","奋衣野田中，今日嗟无负。","兀傲迷东西，蓑笠不能守。","倾倒强行行，酣歌归五柳。","生事不曾问，肯媿家中妇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-f1841dee-c465-42ed-83ec-a1e6c2ca8113","tags":[]},{"id":"poem-5790e32f5e2c8c38b7116869","title":"送陈秀才赴举兼寄韩舍人","author":"贯休","dynasty":"唐","verses":["主圣臣贤日，求名莫等闲。","直须诗似玉，不用力如山。","草白兵初息，年丰驾已还。","凭将安养意，一说向曾颜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-549bc28c-406c-4398-a205-e2b12036405b","tags":[]},{"id":"poem-579e1453bd2817936bfcfb02","title":"横吹曲辞 陇头水","author":"王建","dynasty":"唐","verses":["陇水何年陇头别，不在山中亦呜咽。","征人塞耳马不行，未到陇头闻水声。","谓是西流入蒲海，还闻北海绕龙城。","陇东陇西多屈曲，野麋饮水长簇簇。","胡兵夜回水傍住，忆著来时磨劒处。","向前无井复无泉，放马回看陇头树。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-25651b06-a58e-405f-a539-a86385e96468","tags":[]},{"id":"poem-57a29a26b1245446bcda19b4","title":"奉和御制早春","author":"徐铉","dynasty":"宋","verses":["群生遂性得天真，阳景无私发秀匀。","尧历永从新律正，皇恩散作万方春。","华林日丽红苞拆，太液冰消绿浪新。","天意分明启昌运，岱宗即看报群神。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-38e9dab4-5c2a-4c5c-8c4e-99fa9b1f41b9","tags":["泰山"]},{"id":"poem-57a7ca47b5b933d4603294fe","title":"浣溪沙·咏五更，和湘真韵","author":"纳兰性德","dynasty":"清","verses":["微晕娇花湿欲流，簟纹灯影一生愁。","梦回疑在远山楼。","残月暗窥金屈戍，软风徐荡玉帘钩。","待听邻女唤梳头。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-79","tags":[]},{"id":"poem-57c3b377dfb843ff3dd66301","title":"慈恩寺塔下避暑","author":"刘得仁","dynasty":"唐","verses":["古松凌巨塔，修竹映空廊。","竟日闻虚籁，深山只此凉。","僧真生我静，水淡发茶香。","坐久东楼望，钟声振夕阳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-d10f711a-b2a1-4f39-8b6a-220594025cb2","tags":[]},{"id":"poem-57cb2f298f20d587e49603e9","title":"楚江怀古三首 三","author":"马戴","dynasty":"唐","verses":["野风吹蕙带，骤雨滴兰桡。","屈宋魂冥寞，江山思寂寥。","阴霓侵晚景，海树入回潮。","欲折寒芳荐，明神讵可招。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-44c18e0b-fd4a-42b5-a4fa-866ac8d74d54","tags":[]},{"id":"poem-57d39aeedc269d8e0b429d53","title":"早春左省寓直","author":"徐铉","dynasty":"宋","verses":["旭景鸾台上，微云象阙间。","时清政事少，日永直官闲。","远籁飞箫管，零冰响珮环。","终军年二十，默坐叩玄关。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-20bc47aa-33c7-48bb-94aa-842b5d83b4e1","tags":[]},{"id":"poem-57dcbd690ff358d189b2641f","title":"初食荔枝  其二","author":"张栻","dynasty":"宋","verses":["照水依山祇自奇，晞风沐雨借光辉。","冰肌不受红尘涴，赪颊从教酒晕肥。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-c51614b4-8fde-40cc-adbc-04a926549f0e","tags":[]},{"id":"poem-57e73c73343ca416c535732d","title":"南海子·相风微动九门开","author":"纳兰性德","dynasty":"清","verses":["相风微动九门开，南陌离宫万柳栽。","草色横粘下马泊，水光平占晾鹰台。","锦鞯欲射波间去，玉辇疑从岛上回。","自是软红惊十丈，天教到此洗尘埃。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-255","tags":[]},{"id":"poem-57f48ee566f236cbba626805","title":"·","author":"李揆","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-c4798ce9-c3a2-400f-8c32-7128450b0409","tags":[]},{"id":"poem-57f50bafaa5ea4676f9ccc3c","title":"河传·渺莽云水","author":"张泌","dynasty":"五代","verses":["渺莽云水，惆怅暮帆，去程迢递。","夕阳芳草，千里万里，雁声无限起。","梦魂悄断烟波里，心如醉。","相见何处是，锦屏香冷无睡，被头多少泪。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-39","tags":[]},{"id":"poem-580612a59baccaf882b9b20a","title":"颂古三十一首  其二","author":"释安永","dynasty":"宋","verses":["不因一事，不长一智。","不曾杀生，了无忌讳。","传言送语当风流，拈得口兮失却鼻。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-3344b691-bf46-40d3-983d-4dcfb5e2cda9","tags":[]},{"id":"poem-580ca1dee1a6d65c1bfe718e","title":"江城子·浣花溪上见卿卿","author":"张泌","dynasty":"五代","verses":["浣花溪上见卿卿，脸波明，黛眉轻。","绿云高绾，金族小蜻蜓。","好是问他来得么？和笑道：莫多情。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-1","tags":[]},{"id":"poem-580dd9071ad807f507543183","title":"送何召下第后归蜀","author":"卢纶","dynasty":"唐","verses":["襃斜行客过，栈道响危空。","路湿云初上，山明日正中。","水程通海货，地利杂吴风。","一别金门远，何人复荐雄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-357b89f6-fc6f-4aa2-b158-6da38f820c6b","tags":[]},{"id":"poem-58172412a9a6f5765e23af7d","title":"定风波·莫听穿林打叶声","author":"苏轼","dynasty":"宋","verses":["莫听穿林打叶声。","何妨吟啸且徐行。","竹杖芒鞋轻胜马。","谁怕。","一蓑烟雨任平生。","料峭春风吹酒醒。","微冷。","山头斜照却相迎。","回首向来萧瑟处。","归去。","也无风雨也无晴。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-40","tags":["宋词三百首"]},{"id":"poem-581aa6b615e660976019c00a","title":"同和咏楼前海石榴二首 一","author":"孙逖","dynasty":"唐","verses":["客自新亭郡，朝来数物华。","传君妓楼好，初落海榴花。","露色珠帘映，香风粉壁遮。","更宜林下雨，日晚逐行车。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-f35caecc-8e5c-40ca-a748-223a43ca910c","tags":[]},{"id":"poem-581da330f802510db7ad918d","title":"失调名·彩衣长久","author":"陈瓘","dynasty":"宋","verses":["彩衣长久。","五世祥烟熏舞袖。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-565","tags":[]},{"id":"poem-582a636b3c6d18154dfa066a","title":"句  其四","author":"孟宾于","dynasty":"宋","verses":["仙岛却回空说梦，清朝未达自嫌身。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-8d01534a-ce60-4a98-a79d-61215699c253","tags":[]},{"id":"poem-582e66a2d267ad4949825952","title":"蛮牌令","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［外］儿婿往京畿，前日附书回。","道重婚丞相女，使母弃前妻。","我儿道：非夫写的，你嫂嫂怒从心起。","真和假俱未知，为此特来询问详细。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8186","tags":[]},{"id":"poem-5846b84d","title":"长歌行","author":"佚名","dynasty":"汉","verses":["青青园中葵，朝露待日晞。","阳春布德泽，万物生光辉。","常恐秋节至，焜黄华叶衰。","百川东到海，何时复西归？","少壮不努力，老大徒伤悲。"],"enabled":true,"collection":"历代名篇","source":"《乐府诗集》相和歌辞《长歌行》。","tags":["乐府","惜时"]},{"id":"poem-584d4674c1a32790712059bd","title":"句","author":"解叔禄","dynasty":"唐","verses":["千花苑外韶芳暖，一鸟山边翠色寒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-adaf34f4-56bc-4f09-a5b2-849fd10bc12b","tags":[]},{"id":"poem-585194d11607297787e23e87","title":"宫词  其三八","author":"张公庠","dynasty":"宋","verses":["玉堂催下葳蕤锁，除授唯容学士知。","丞相捧麻宣读了，百僚欣惬拜丹墀。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-0146a511-22e7-4a76-9d6a-e13e9fbbac83","tags":[]},{"id":"poem-5852602335cd8ecb5a0c3cfb","title":"苦热行","author":"僧鸾","dynasty":"唐","verses":["烛龙衔火飞天地，平陆无风海波沸。","彤云叠叠耸奇峰，焰焰流光热凝翠。","烟岛抟鹏亸双翅，羲和赫怒强总辔。","饮流夸父毙长途，如见当中印王字。","明明夜西朝又东，古来有道仍再中。","扶桑老叶蔽不得，辉华直欲凌苍空。","行人挥汗翻成雨，口燥喉干嗌尘土。","西郊云色昼冥冥，如何不救生灵苦。","何山怪木藏蛟龙，缩鳞卷鬣为乖慵。","不发滂泽注天下，欲使风雷何所从。","旱苗原上枯成焰，岳灵徒祝无神验。","豪家帘外唤清风，水纹明角铺长簟。","玉扇画堂凝夜秋，歌艳绕梁催莫愁。","阳乌落尽酒不醒，扶上西园当月楼。","废田暍死非吾属，库有黄金仓有粟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-015bfef1-49e4-4499-83a4-fe6b8cf37c0b","tags":[]},{"id":"poem-585a3486d1fc64b7720605b6","title":"句","author":"王铎","dynasty":"唐","verses":["华表尚迷丁令鹤，竹坡犹认葛溪龙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-c3ba9321-6bc3-4af7-9e0d-5b6ddab1a1ad","tags":[]},{"id":"poem-58600e3ade3d0a4c00da1192","title":"由皖口归升州作（题拟）","author":"徐铉","dynasty":"唐","verses":["一夜黄星照官渡，本初何面见田丰？","（《徐公文集》附《徐铉行状》引。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-0b9259e1-e009-4464-ad79-6f0afb5253e0","tags":[]},{"id":"poem-586255cdd7e2c89d777ddee0","title":"无羊","author":"佚名","dynasty":"先秦","verses":["谁谓尔无羊？三百维群。谁谓尔无牛？九十其犉。尔羊来思，其角濈濈。尔牛来思，其耳湿湿。","或降于阿，或饮于池，或寝或讹。尔牧来思，何蓑何笠，或负其糇。三十维物，尔牲则具。","尔牧来思，以薪以蒸，以雌以雄。尔羊来思，矜矜兢兢，不骞不崩。麾之以肱，毕来既升。","牧人乃梦，众维鱼矣，旐维旟矣，大人占之；众维鱼矣，实维丰年；旐维旟矣，室家溱溱。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-189","tags":[]},{"id":"poem-5874b54c3ca56e7127862f11","title":"月","author":"徐夤","dynasty":"唐","verses":["碧落谁分造化权，结霜凝雪作婵娟。","寒蝉若不开三穴，狡兔何从上九天。","莫见团圆明处远，须看湾曲鉴时偏。","郄诜树老尧蓂换，惆怅今年似去年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-7710181b-8ad9-4df0-ab26-5268fe33d0e1","tags":[]},{"id":"poem-58752011c6c8fb7e5c00f837","title":"氐州第一·波落寒汀","author":"周邦彦","dynasty":"宋","verses":["波落寒汀，村渡向晚，遥看数点帆小。","乱叶翻鸦，惊风破雁，天角孤云缥缈。","官柳萧疏，甚尚挂、微微残照。","景物关情，川途换目，顿来催老。","渐解狂朋欢意少。","奈犹被、思牵情绕。","座上琴心，机中锦字，觉最萦怀抱。","也知人、悬望久，蔷薇谢、归来一笑。","欲梦高唐，未成眠、霜空又晓。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-413","tags":[]},{"id":"poem-5883cbf92d3be9706cfd5b47","title":"于中好·十月初四夜风雨其明日是亡妇生辰","author":"纳兰性德","dynasty":"清","verses":["尘满疏帘素带飘，真成暗度可怜宵。","几回偷拭青衫泪，忽傍犀奁见翠翘。","惟有恨，转无聊。","五更依旧落花朝。","衰杨叶尽丝难尽，冷雨凄风打画桥。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-124","tags":[]},{"id":"poem-5887c8e39a046077164c1808","title":"春更书怀","author":"吕从庆","dynasty":"唐","verses":["丰溪村内野人居，隐约南山对敝庐。","花下小桥春策蹇，竹中深径夜归渔。","无名正可骄王谢，有句还能继庾徐。","醉罢浊醪邻客散，一番清梦又蘧蘧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-9651de83-f3bd-4bba-b746-cd206f017493","tags":[]},{"id":"poem-588dde2692c2fdef66a98a08","title":"劝人 十二","author":"义存","dynasty":"唐","verses":["君不见（《祖堂集》卷七「不见」二字作「觅」）路边华表柱，天下忙忙总一般。","琵琶柦棙（《祖堂集》作「拗捩」）随手转，广陵妙曲无人弹。","若有人能解弹得，一弹弹尽天下曲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-3e3974dd-97fa-492b-9659-b3eece0aaf8b","tags":[]},{"id":"poem-5894e0f9920b2b8e5d316779","title":"五月水边柳","author":"张又新","dynasty":"唐","verses":["结根挺涯涘，垂影覆清浅。","睡脸寒未开，嬾腰晴更软。","摇空条已重，拂水带方展。","似醉烟景凝，如愁月露泫。","丝长鱼悮恐，枝弱禽惊践。","怅别几多情，含春任攀搴。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-f6848174-0e38-41e8-90df-8015dc3afcef","tags":["咏物","咏物诗","柳树"]},{"id":"poem-589a2f05ba41afb0dc8147cf","title":"蚕妇","author":"来鹄","dynasty":"唐","verses":["晓夕采桑多苦辛，好花时节不闲身。","若教解爱繁华事，冻杀黄金屋里人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-491e12d6-4fb9-4c00-b315-9fdf952f3f6d","tags":["写人","讽喻","写人诗"]},{"id":"poem-58a723f3a884c4c341fe37b6","title":"南歌子·睡起临窗坐","author":"晁补之","dynasty":"宋","verses":["睡起临窗坐，妆成傍砌闲。","春来莫卷绣帘看。","嫌怕东风吹恨、在眉间。","鹦鹉花前弄，琵琶月下弹。","蓦然收袖倚栏干。","一向思量何事、点云鬟。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-276","tags":[]},{"id":"poem-58ba841066f79c3ffe8f2b62","title":"碧角簟","author":"曹松","dynasty":"唐","verses":["细皮重叠织霜纹，滑腻铺床胜锦茵。","八尺碧天无点翳，一方青玉绝纤尘。","蝇行只恐烟黏足，客卧混疑水浸身。","五月不教炎气入，满堂秋色冷龙鳞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-86ed60df-bb60-4663-98c4-008fc8facbae","tags":[]},{"id":"poem-58bbe04dfa00bdcc1f069b81","title":"浣溪沙·夜夜相思更漏残","author":"韦庄","dynasty":"五代","verses":["夜夜相思更漏残，伤心明月凭栏干，想君思我锦衾寒。","咫尺画堂深似海，忆来唯把旧书看，几时携手入长安。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-32","tags":[]},{"id":"poem-58bf4162e87febdf329a86ac","title":"横吹曲辞 关山月","author":"李白","dynasty":"唐","verses":["明月出天山，苍茫云海间。","长风几万里，吹度玉门关。","汉下白登道，胡窥青海湾。","由来征战地，不见有人还。","戍客望边色，思归多苦颜。","高楼当此夜，叹息未应闲。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-4be77185-992e-4614-9746-de2e73c8a3c3","tags":["唐诗三百首","中秋","边塞","山","思乡","乐府","描写山","写山","征人"]},{"id":"poem-58c6385d966eb0fcee62e874","title":"句 一","author":"高骈","dynasty":"唐","verses":["手栽桃李十余春，今日经过重建勋。","（《经虢县》。","见崔致远《桂苑笔耕集》卷十七《磻溪》诗自注引高骈句。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-54f295e5-7eed-4deb-8f79-e3b77d9f4795","tags":[]},{"id":"poem-58ceaaffe5a1f10bd7cf8a35","title":"送萧颖士赴东府得还字","author":"房白","dynasty":"唐","verses":["夫子高世迹，时人不可攀。","今予亦云幸，谬得承温颜。","良策资入幕，遂行从近关。","青春灞亭别，此去何时还。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-70847d6a-a1e9-4b6f-a904-25924ca4c875","tags":[]},{"id":"poem-58e066624d2f8aafef71ad00","title":"酒泉子·小槛日斜","author":"顾敻","dynasty":"五代","verses":["小槛日斜，风度绿窗人悄悄。","翠帷闲掩舞双鸾，旧香寒。","别来情绪转难拚，韶颜看却老。","依稀粉上有啼痕，暗销魂。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-10","tags":[]},{"id":"poem-58e1e997f54619d5cecb37ae","title":"题开圣寺","author":"李涉","dynasty":"唐","verses":["宿雨初收草木浓，群鸦飞散下堂钟。","长廊无事僧归院，尽日门前独看松。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-4d9dbc25-afa4-4316-95b6-abba6bd0f8c6","tags":[]},{"id":"poem-58edd503da3e58f713d6113a","title":"酬张三十秀才见赠","author":"司马光","dynasty":"宋","verses":["朴学居人后，清涂忝众先。","瓠因无用弃，木为不才全。","比得林泉趣，仍依邑里贤。","自惭头半白，方解赋归田。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-492d5e3f-98bd-43f0-8795-933dcf0314d2","tags":[]},{"id":"poem-58f245e4eedebe2e1ba747fe","title":"送神","author":"司空曙","dynasty":"唐","verses":["神之去，回风袅袅云容与。","桂尊瑶席不复陈，苍山绿水暮愁人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-96d11aa0-418d-4fb9-a31c-248cb6edb341","tags":[]},{"id":"poem-58f3c6db954245193fbaa19f","title":"佛鉴和尚","author":"释了惠","dynasty":"宋","verses":["灵而不灵，不灵而灵。","鬼不是鬼，神不是神。","讪谤祖宗之魔孽，惑乱男女之妖精。","天童一见便生嗔，未必灵岩肯卜邻。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-794b9797-167e-4dbb-af62-62ded9a08c6d","tags":[]},{"id":"poem-58f5294283f5a5ccb86dc644","title":"调笑令","author":"杨景贤","dynasty":"元","verses":["来到这洞边，叫声喧，休猜做落日山空啼杜鹃，天兵布得山川通。","(行者云)上圣，这厮神通广大，神力周全。","(二郎唱)孙行者说言在驷马之前，你道他神通广大自专，则好深山里唬地瞒天。","(猪内做惊科)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4528","tags":[]},{"id":"poem-58f6a55edf2c504e937da2b5","title":"送刘贡甫贬衡州","author":"刘跂","dynasty":"宋","verses":["洞庭木叶下，衡阳鸿雁飞。","放舟河之水，岁暮以为期。","岂曰无径路，大直固逶迤。","波平弭桂棹，风清卷兰旗。","紫蟹间丹鲤，霜莼兼露葵。","醉歌搴杜若，还以寄相思。","不厌道里远，所嗟时序移。","会登昆仑丘，遂索玄珠遗。","以兹鼓枻去，瞠若不可追。","乃知体道人，涉世自有宜。","入兽不乱群，安肯陋九夷。","如何录录者，反笑抱关为。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-16de7c00-5557-4895-aff2-3197d3401a7a","tags":["洞庭湖"]},{"id":"poem-59024eb9a8af8363c45b96a7","title":"湘春夜月·近清明","author":"黄孝迈","dynasty":"宋","verses":["近清明。","翠禽枝上消魂。","可惜一片清歌，都付与黄昏。","欲共柳花低诉，怕柳花轻薄，不解伤春。","念楚乡旅宿，柔情别绪，谁与温存。","空樽夜泣，青山不语，残月当门。","翠玉楼前，惟是有、一波湘水，摇荡湘云。","天长梦短，问甚时、重见桃根。","这次第，算人间没个并刀，翦断心上愁痕。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-0","tags":["宋词三百首"]},{"id":"poem-5909d58c585fea433397592e","title":"送青阳上人游越","author":"孟郊","dynasty":"唐","verses":["秋风吹白发，微官自萧索。","江僧何用叹，溪县饶寂寞。","楚思物皆清，越山胜非薄。","时看镜中月，独向衣上落。","多谢入冥鸿，笑予在笼鹤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-6396f1dc-ee8a-4de1-a0b6-27790160e4ad","tags":[]},{"id":"poem-5909f0c60096e9aba55a68b9","title":"咸阳送房济侍御归太原幕","author":"卢纶","dynasty":"唐","verses":["旧居无旧邻，似见故乡春。","复对别离酒，欲成衰老人。","客衣频染泪，军旅亦多尘。","握手重相勉，平生心所因。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-dacfff7a-fffe-423e-9c52-14f2efccae80","tags":[]},{"id":"poem-590e6d2150f02ea095d949dd","title":"宫词  其一四","author":"张公庠","dynasty":"宋","verses":["晓雾溟蒙似有无，半残红烛动金铺。","黄莺不语梨花上，错认徐熙旧画图。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-6e8f1d9a-a0ba-4f6e-98e1-a8b9b3f065b8","tags":[]},{"id":"poem-591c86591d1f7fe8eca5c47b","title":"太皇太后挽歌词二首  其二","author":"司马光","dynasty":"宋","verses":["四纪袆衣盛，两朝长乐尊。","九州贡甘旨，万乘问晨昏。","明辟归元子，嘉谋赉孝孙。","群生资后土，难答化光恩。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-077d67fb-a2cf-4e33-860a-d4ce1157f913","tags":[]},{"id":"poem-591d71cab8cbccb39d9cca68","title":"春过鄱阳湖","author":"贯休","dynasty":"唐","verses":["百虑片帆下，风波极目看。","吴山兼鸟没，楚色入衣寒。","过此愁人处，始知行路难。","夕阳沙岛上，回首一长叹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-da1610bf-679f-49e6-8ab3-2e926f45ccc3","tags":[]},{"id":"poem-591f29b4fb3b15ab66120d32","title":"画猿","author":"孙嵩","dynasty":"宋","verses":["客子平生三峡游，青猿树树悬高秋。","归来落笔成天趣，中传蜀月巴云意。","如何猿叫驿边时，只欠行人唱竹枝。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-5e4292bd-1ddf-4a80-80f4-331f4286c824","tags":[]},{"id":"poem-59231788a5cccc53fe6bfe31","title":"行香子·草色芊绵","author":"赵鼎","dynasty":"宋","verses":["草色芊绵。","雨点阑斑。","糁飞花、还是春残。","天涯万里，海上三年。","试倚危楼，将远恨，卷帘看。","举头见日，不见长安。","谩凝眸、老泪凄然。","山禽飞去，榕叶生寒。","到黄昏也，独自个，尚凭阑。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-979","tags":[]},{"id":"poem-59275494bc0f32f9acc2a939","title":"·","author":"李昉","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-cd6fc024-4b18-4f7e-a4c5-d4f60aebc5b5","tags":[]},{"id":"poem-592ff5ba6d4af40081c93705","title":"送赵君权中归福唐兼呈陈季中","author":"苏颂","dynasty":"宋","verses":["赵子抱经术，儒林挺孤秀。","策足入上庠，高谊诸生右。","秋闱再程文，怀宝不见售。","京师首善地，翘然俊贤囿。","朝廷举新诏，多士四方走。","主司搜择艰，有如羿张彀。","小善或不遗，宁当舍良茂。","岂非绳准高，刀尺下难就。","得丧不在己，自信非我疚。","岁穷感亲心，倚门方远候。","都亭谢知己，飘飘拂归袖。","乐彼闽中幽，里中贤友旧。","且复从其游，行义益充厚。","道存贵有用，独善古所陋。","明时无滞才，子行当勉懋。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-4129a603-29ee-49e7-9e58-b9ca397c0b29","tags":[]},{"id":"poem-593079aef075487cdb64dd48","title":"别卢秦卿","author":"司空曙","dynasty":"唐","verses":["知有前期在，难分此夜中。","无将故人酒，不及石尤风。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-別盧秦卿","tags":[]},{"id":"poem-593190aa19c8b55b82dd4b57","title":"柳枝词十首  其一","author":"徐铉","dynasty":"宋","verses":["金马词臣赋小诗，梨园弟子唱新词。","君恩还似东风意，先入灵和蜀柳枝。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-5b740bd6-94a9-46be-a13b-451c1f060499","tags":[]},{"id":"poem-5933734c5118dd1b7cea6030","title":"柳枝·袅翠笼烟拂暖波","author":"牛峤","dynasty":"五代","verses":["袅翠笼烟拂暖波，舞裙新染麹尘罗。","章华台畔隋堤上，傍得春风尔许多。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-49","tags":[]},{"id":"poem-5939c883dfbdd0791948fefe","title":"酬韩庶子","author":"张籍","dynasty":"唐","verses":["西街幽僻处，正与嬾相宜。","寻寺独行远，借书常送迟。","家贫无易事，身病足闲时。","寂寞谁相问，祗应君自知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-b05412b6-d656-4086-a022-771c4f0dfad9","tags":[]},{"id":"poem-593b5207825e3885fdecfeb7","title":"车攻","author":"佚名","dynasty":"先秦","verses":["我车既攻，我马既同。四牡庞庞，驾言徂东。","田车既好，田牡孔阜。东有甫草，驾言行狩。","之子于苗，选徒嚣嚣。建旐设旄，搏兽于敖。","驾彼四牡，四牡奕奕。赤芾金舄，会同有绎。","决拾既佽，弓矢既调。射夫既同，助我举柴。","四黄既驾，两骖不猗。不失其驰，舍矢如破。","萧萧马鸣，悠悠旆旌。徒御不惊，大庖不盈。","之子于征，有闻无声。允矣君子，展也大成。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-178","tags":[]},{"id":"poem-59445f444318af35129e2617","title":"谢池春慢·缭墙重院","author":"张先","dynasty":"宋","verses":["缭墙重院，时闻有、啼莺到。","绣被掩馀寒，画幕明新晓。","朱槛连空阔，飞絮无多少。","径莎平，池水渺。","日长风静，花影闲相照。","尘香拂马，逢谢女、城南道。","秀艳过施粉，多眉生轻笑。","斗色鲜衣薄，碾玉双蝉小。","欢难偶，春过了。","琵琶流怨，都入相思调。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-279","tags":[]},{"id":"poem-594946ecbe3a11b7a6957f26","title":"月上海棠","author":"施惠《幽闺记》","dynasty":"元","verses":["(外)你自想，甚年发迹穷形状？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3009","tags":[]},{"id":"poem-594c22bf3d7c460858e43324","title":"天柱庵","author":"陈岩","dynasty":"宋","verses":["石壁参天驻冷云，一声幽鸟忽惊人。","庵前庵后山如旧，朽柏年来不再春。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-e7a94f0b-f265-4a06-b823-451dbbe3441a","tags":[]},{"id":"poem-594ccfcffed024cfde777333","title":"浣溪沙·欲上秋千四体慵","author":"韦庄","dynasty":"五代","verses":["欲上秋千四体慵，拟教人送又心忪。画堂帘幕月明风。","此夜有情谁不极，隔墙梨雪又玲珑，玉容憔悴惹微红。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-29","tags":[]},{"id":"poem-594e5c48f004bb11ca1990e1","title":"多景楼","author":"张栻","dynasty":"宋","verses":["畴昔南徐地，登临北固楼。","平原迷故国，沧海接江流。","木落烟莎晚，城孤鼓角秋。","寄言鸥鹭侣，吾已具扁舟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-4ce3dd34-fd42-4444-a26b-84e4f4859707","tags":[]},{"id":"poem-595d2c4ed17cd533c95aaafe","title":"新堤","author":"赵崇鉘","dynasty":"宋","verses":["淡烟衰草雨丝丝，小醉微吟倒接篱。","吟到水西云影北，莞然一笑已无诗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-b97f70b7-1d14-4998-b2b2-3510e3acbba6","tags":[]},{"id":"poem-5960ce747cbcb266093cdc3b","title":"寒食城东即事","author":"王维","dynasty":"唐","verses":["清溪一道穿桃李，演漾绿蒲涵白芷。","溪上人家凡几家，落花半落东流水。","蹴鞠屡过飞鸟上，秋千竞出垂杨里。","少年分日作遨游，不用清明兼上巳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-a5a19b2c-d215-4b3e-8b8c-29d9da7bccce","tags":["描写水","闲适","写鸟","写水","鸟"]},{"id":"poem-5964f154cf0fdc32a22ec1e7","title":"和徐先辈秋日游泾州南亭呈三二同年","author":"姚鹄","dynasty":"唐","verses":["多此欢情泛鹢舟，桂枝同折塞同游。","声喧岛上巢松鹤，影落杯中过水鸥。","送日暮钟交戍岭，呌云寒角动城楼。","酒酣笑语秋风里，谁道槐花更起愁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-1f8ac12d-7aee-40e0-842b-1f37e00c53d2","tags":[]},{"id":"poem-59689f9870924d6c9fbd141c","title":"齐天乐·一襟馀恨宫魂断","author":"王沂孙","dynasty":"宋","verses":["一襟馀恨宫魂断，年年翠阴庭树。","乍咽凉柯，还移暗叶，重把离愁深诉。","西窗过雨。","怪瑶佩流空，玉筝调柱。","镜暗妆残，为谁娇鬓尚如许。","铜仙铅泪似洗，叹携盘去远，难贮零露。","病翼惊秋，枯形阅世，消得斜阳几度。","馀音更苦。","甚独抱清高，顿成凄楚。","谩想薰风，柳丝千万缕。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-250","tags":["宋词三百首"]},{"id":"poem-596c1f471c7f4a27efc3ebfc","title":"萍乡春晚寓居（四首） 二","author":"沈彬","dynasty":"唐","verses":["花替残红草绿深，江头闲事岂堪寻。","云山忆后思藏迹，家国话来长痛心。","战地血流犹未服，侯门心热更相歆。","求归闲处无闲处。","三纪兵戈犹至今。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-6bfafaf6-4ac2-461b-9c53-57da42d15c96","tags":[]},{"id":"poem-596ce6adea498a46863ddb17","title":"永明山居诗（六十九首） 六十一","author":"延寿","dynasty":"唐","verses":["散诞疎狂得自然，免教拘迫事相牵。","潜龙不离滔滔水，孤鹤唯宜远远天。","透室寒光松槛月，逼人凉气石渠泉。","非吾独了西来意，竹祖桐孙尽入玄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-1e41570a-9d95-4b14-bf1a-42cc63d986a6","tags":[]},{"id":"poem-5979a77c138944a38cb9d0a9","title":"水龙吟·似花还似非花","author":"苏轼","dynasty":"宋","verses":["似花还似非花，也无人惜从教坠。","抛家傍路，思量却是，无情有思。","萦损柔肠，困酣娇眼，欲开还闭。","梦随风万里，寻郎去处，又还被、莺呼起。","不恨此花飞尽，恨西园、落红难缀。","晓来雨过，遗踪何在，一池萍碎。","春色三分，二分尘土，一分流水。","细看来，不是杨花点点，是离人泪。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-37","tags":["宋词三百首"]},{"id":"poem-59847de96cb9aad740e56639","title":"剪彩花","author":"雍裕之","dynasty":"唐","verses":["敢竞桃李色，自呈刀尺功。","蝶犹迷剪翠，人岂辨裁红。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-5f0e0450-dc67-42b1-b59d-718213cee4b4","tags":[]},{"id":"poem-59896f4641b66e7d13384fa5","title":"延平门高斋亭子应岐王教","author":"张谔","dynasty":"唐","verses":["花源药屿凤城西，翠幕纱窗莺乱啼。","昨夜蒲萄初上架，今朝杨柳半垂堤。","片片仙云来渡水，双双燕子共衔泥。","请语东风催后骑，倂将歌舞向前谿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-c869f274-e9ed-452a-b3b6-fa246a95be0d","tags":[]},{"id":"poem-59911015147486fb40c849b9","title":"忆虎序","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["当初娶汝，(净)正是大盘大盒娶的。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8234","tags":[]},{"id":"poem-5991edda18ce30b1beb06294","title":"杨生青花紫石砚歌","author":"李贺","dynasty":"唐","verses":["端州石工巧如神，踏天磨刀割紫云。","佣刓抱水含满唇，暗洒苌弘冷血痕。","纱帷昼暖墨花春，轻沤漂沫松麝薰。","干腻薄重立脚匀，数寸光秋无日昏。","圆毫促点声静新，孔砚宽顽何足云。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-dadedde0-d4fd-44e4-8805-586ed3717ef7","tags":["咏物诗","咏物","赞美","砚石"]},{"id":"poem-599826a804e46211f2f5a47b","title":"牧童词","author":"张籍","dynasty":"唐","verses":["远牧牛，遶村四面禾黍稠。","陂中饥乌啄牛背，令我不得戏垅头。","入陂草多牛散行，白犊时向芦中鸣。","隔堤吹叶应同伴，还鼓长鞭三四声。","牛牛食草莫相触，官家截尔头上角。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-0a89bd17-bf77-4229-aed9-1418f67081e4","tags":[]},{"id":"poem-599d566331c78aa1098de32b","title":"奉和圣制送张说上集贤学士赐宴","author":"李元纮","dynasty":"唐","verses":["硕儒延凤沼，金马被鸿私。","馔玉趋丹禁，牋花降紫墀。","衔恩倾旨酒，鼓舞咏康时。","暂觏群书缉，逾昭盛业丕。","接筵欣有命，搦管媿无词。","自惊一何幸，太阳还及葵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-96575e78-6563-4419-8738-89a08b43f83f","tags":[]},{"id":"poem-59ac61d4ed7f067ee22b6db0","title":"三学士","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["谢得公公意甚美，凡事仗托维持。","假饶一举登科日，难道是双亲未老时。","只恐锦衣归故里，双亲的怕不见儿。","(外唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4938","tags":[]},{"id":"poem-59b0353fb29a32b2f5167e15","title":"句","author":"李许","dynasty":"唐","verses":["澹荡和风催去袖，摇扬淑景照离樽。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-b6ef1ad9-7c70-4246-9471-16ccc3bbd684","tags":[]},{"id":"poem-59c292210ec9da26943d950f","title":"木兰花·小芙蓉","author":"魏承班","dynasty":"五代","verses":["小芙蓉，香旖旎，碧玉堂深清似水。","闭宝匣，掩金铺，倚屏拖袖愁如醉。","迟迟好景烟花媚，曲渚鸳鸯眠锦翅。","凝然愁望静相思，一双笑靥嚬香蕊。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-1","tags":[]},{"id":"poem-59c4bae1b9db388ba52762fe","title":"冬初杂兴  其三","author":"孙嵩","dynasty":"宋","verses":["钟声烟外寺，报我明朝霜。","篱落暝雀惊，原野昏鸦翔。","杖策归茅茨，偶一歌慨慷。","千载有我辈，感念行斜阳。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-811f3966-0b9e-4b28-b392-66a4c3414da7","tags":[]},{"id":"poem-59d3f7000fe222ece0b9d080","title":"乐府杂词三首 二","author":"刘言史","dynasty":"唐","verses":["蝉鬓红冠粉黛轻，云和新教羽衣成。","月光如雪金堦上，迸却颇梨义甲声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-15fe86ed-edfe-4f94-86fd-8877d8d97182","tags":[]},{"id":"poem-59e89a5e93835f49479e2d74","title":"新台","author":"佚名","dynasty":"先秦","verses":["新台有泚，河水弥弥。燕婉之求，蘧篨不鲜。","新台有洒，河水浼浼。燕婉之求，蘧篨不殄。","鱼网之设，鸿则离之。燕婉之求，得此戚施。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-42","tags":[]},{"id":"poem-59ea7ba9322ac583ec68b79e","title":"朱奴儿","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［净］因科举离乡半春，从别后断羽绝鳞。","今日天教遇你们，趁良使附归音信。","［合］还历尽山郭水村，指日到东瓯郡。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8170","tags":[]},{"id":"poem-59ece5b6878b99c0d76468ef","title":"孝顺歌","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["呕得我肝肠痛，珠泪垂，喉咙尚兀自牢嗄住。","糠！遭砻被舂杵，筛你簸扬你，吃尽控持。","悄似奴家身狼狈，千辛万苦皆经历。","苦人吃着苦味，两苦相逢，可知道欲吞不去。","(吃吐介)(唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5073","tags":[]},{"id":"poem-59f6ffd85a3570e7a3c107e2","title":"白菊三首 一","author":"司空图","dynasty":"唐","verses":["不疑陶令是狂生，作赋其如有定情。","犹胜江南隐居士，诗魔终袅负孤名。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-0df27fd6-291b-49e4-9e42-94afbbbae717","tags":[]},{"id":"poem-59f99c42dab7727809fca1ac","title":"更漏子·鹊桥边","author":"向子𬤇","dynasty":"宋","verses":["鹊桥边，牛渚上。","翠节红旌相向。","承玉露，御金风。","年年岁岁同。","懒飞梭，停弄杼。","遥想彩云深处。","人咫尺，事关山。","无聊独倚栏。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-762","tags":[]},{"id":"poem-59fa65292ab5c2a6bc6d0a0d","title":"题包山","author":"皮日休","dynasty":"唐","verses":["一片烟村胜画图，四边波浪送清虚。","此中人若无租税，直是蓬瀛也不如。","（见《分门䉤类唐歌诗》残本第四册《天地山川类》。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-958461ca-1d08-4483-b6ee-53e7db173359","tags":[]},{"id":"poem-59fd886b36a120f8069a8156","title":"郊庙歌辞 享太庙乐章 雍和","author":"魏征、褚亮","dynasty":"唐","verses":["於穆清庙，聿修严祀。","四县载陈，三献斯止。","笾豆彻荐，人祇介祉。","神维格思，锡祚不已。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-3776e703-3ed3-4c65-95ea-62eed3e929c0","tags":[]},{"id":"poem-59fdac7cc89ccec49adfbb47","title":"济上四贤咏 崔录事","author":"王维","dynasty":"唐","verses":["解印归田里，贤哉此丈夫。","少年曾任侠，晚节更为儒。","遯迹东山下，因家沧海隅。","已闻能狎鸟，余欲共乘桴。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-f0f00c03-fb54-408b-b62b-a11cc62461f2","tags":[]},{"id":"poem-5a0f9c68253aadf2fbf027b1","title":"渡荆门送别","author":"李白","dynasty":"唐","verses":["渡远荆门外，来从楚国游。","山随平野尽，江入大荒流。","月下飞天镜，云生结海楼。","仍连故乡水，万里送行舟。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-bf8918b8-a05a-4ccf-bb2e-3f9b81f6bbfc","tags":["唐诗三百首","长江","送别","五言律诗","初中古诗","八年级上册(课内)","思乡"]},{"id":"poem-5a16b1db616f5d03eb5efae8","title":"摊破浣溪沙·一霎灯前醉不醒","author":"纳兰性德","dynasty":"清","verses":["一霎灯前醉不醒，恨如春梦畏分明。","淡月淡云窗外雨，一声声。","人道情多情转薄，而今真个不多情。","又听鹧鸪啼遍了，短长亭。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-39","tags":[]},{"id":"poem-5a1e39b5ce318b529924c349","title":"赠郭驸马 一","author":"李端","dynasty":"唐","verses":["青春都尉最风流，二十功成便拜侯。","金距鬬鸡过上苑，玉鞭骑马出长楸。","熏香荀令偏怜少，傅粉何郎不解愁。","日暮吹箫杨柳陌，路人遥指凤凰楼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-d119e9a6-56b9-499a-a23a-3e76c0a12e99","tags":[]},{"id":"poem-5a1f0dae023b43baa9c5c7ed","title":"·","author":"如体","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-71926b01-bec3-4f3f-8709-f29e60a77dcf","tags":[]},{"id":"poem-5a1f486347197533b9ac7da5","title":"殷其雷","author":"佚名","dynasty":"先秦","verses":["殷其雷，在南山之阳。何斯违斯，莫敢或遑？振振君子，归哉归哉！","殷其雷，在南山之侧。何斯违斯，莫敢遑息？振振君子，归哉归哉！","殷其雷，在南山之下。何斯违斯，莫或遑处？振振君子，归哉归哉！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-18","tags":[]},{"id":"poem-5a3f9a130a1dcb5568078c5c","title":"秋月","author":"程颢","dynasty":"宋","verses":["清溪流过碧山头，空水澄鲜一色秋。","隔断红尘三十里，白云红叶两悠悠。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-秋月","tags":[]},{"id":"poem-5a43027245ed11d32395a999","title":"郊庙歌辞 祭汾阴乐章 雍和","author":"贾曾","dynasty":"唐","verses":["蠲我饎餴，絜我膋芗。","有豆孔硕，为羞既臧。","至诚无昧，精意惟芳。","神其醉止，欣欣乐康。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-6c9b601a-649e-4380-8ce3-14e8d40b841f","tags":[]},{"id":"poem-5a4ad75e1ddaf177d0644ca0","title":"巴童荅","author":"李贺","dynasty":"唐","verses":["巨鼻宜山褐，庞眉入苦吟。","非君唱乐府，谁识怨秋深。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-8aee0b0a-cc97-4674-9249-8c4994f3fa28","tags":[]},{"id":"poem-5a4cd502441754281a0dd279","title":"昭君怨·拂晓拿舟东去","author":"张镃","dynasty":"宋","verses":["拂晓拿舟东去。","细看荷花垂露。","红绿总吹香。","一般凉。","会享人天清福。","休把两眉轻蹙。","谁道做神仙。","戴貂蝉。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-321","tags":[]},{"id":"poem-5a5bc7bce362675b2b21700c","title":"颂古七十六首  其三","author":"释士珪","dynasty":"宋","verses":["月里姮娥不画眉，只将云雾作罗衣。","不知梦逐青鸾去，犹把花枝盖面归。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-3512cd67-ab5c-4fac-92a8-de845e74cd22","tags":[]},{"id":"poem-5a64b80ca915ac1552897b4d","title":"始迁青溪望吴兴故里","author":"吴党","dynasty":"唐","verses":["平生愿嗣叔庠微，谁识飘零事已非。","霅水远从云外隔，澄江独向月中归。","烟横野渡行舟稳，露下衡门步屐稀。","潮夕不通音问杳，故乡冷落钓鱼矶。","（光绪十年刊李诗纂《淳安县志》卷十五，原署：「周吴党。","」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-4022a35f-79c9-4e86-96e5-01d564e5ce60","tags":[]},{"id":"poem-5a66ebb5e12a34e81dcadd39","title":"和李太保寄刁秘书","author":"徐铉","dynasty":"宋","verses":["名位虽卑道自光，讼庭无事俗平康。","帘间尚觉琴床暖，院静偏闻酒瓮香。","养性已知无病染，持廉唯恐有名彰。","主人莫讶暌违远，千仞由来有凤翔。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-23b55de9-48fb-4dba-8585-12651bfc2c16","tags":[]},{"id":"poem-5a66fb829e9562229a938fd9","title":"赋得古原草送别","author":"白居易","dynasty":"唐","verses":["离离原上草，一岁一枯荣。","野火烧不尽，春风吹又生。","远芳侵古道，晴翠接荒城。","又送王孙去，萋萋满别情。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-0174cbbc-31fa-4daf-b1cf-7f91c6a646a9","tags":["唐诗三百首","写草","二年级下册","咏物","送别","五言律诗","咏物诗","小学古诗"]},{"id":"poem-5a6868f236d0fc19763c09c9","title":"古意","author":"李颀","dynasty":"唐","verses":["男儿事长征，少小幽燕客。","赌胜马蹄下，由来轻七尺。","杀人莫敢前，须如猬毛磔。","黄云陇底白雪飞，未得报恩不能归。","辽东小妇年十五，惯弹琵琶解歌舞。","今为羗笛出塞声，使我三军泪如雨。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-f1496cf4-4f85-4f9e-9e0e-dd05370641d3","tags":["唐诗三百首","战争","豪侠","拟古","戍边","七言古诗"]},{"id":"poem-5a7244c6d67f7b5a49ac6fd4","title":"板","author":"佚名","dynasty":"先秦","verses":["上帝板板，下民卒瘅。出话不然，为犹不远。","靡圣管管。不实于亶。犹之未远，是用大谏。","天之方难，无然宪宪。天之方蹶，无然泄泄。","辞之辑矣，民之洽矣。辞之怿矣，民之莫矣。","我虽异事，及尔同僚。我即尔谋，听我嚣嚣。","我言维服，勿以为笑。先民有言，询于刍荛。","天之方虐，无然谑谑。老夫灌灌，小子𫏋𫏋。","匪我言耄，尔用忧谑。多将熇熇，不可救药。","天之方懠。无为夸毗。威仪卒迷，善人载尸。","民之方殿屎，则莫我敢葵？丧乱蔑资，曾莫惠我师？","天之牖民，如埙如篪，如璋如圭，如取如携。","携无曰益，牖民孔易。民之多辟，无自立辟。","价人维藩，大师维垣，大邦维屏，大宗维翰，怀德维宁，宗子维城。无俾城坏，无独斯畏。","敬天之怒，无敢戏豫。敬天之渝，无敢驰驱。","昊天曰明，及尔出王。昊天曰旦，及尔游衍。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-253","tags":[]},{"id":"poem-5a7c876e35f996da4dc482d6","title":"鹊桥仙·月波清霁","author":"欧阳修","dynasty":"宋","verses":["月波清霁，烟容明淡，灵汉旧期还至。","鹊迎桥路接天津，映夹岸、星榆点缀。","云屏未卷，仙鸡催晓，肠断去年情味。","多应天意不教长，恁恐把、欢娱容易。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-762","tags":[]},{"id":"poem-5a96dbd270c9f9aa45febae8","title":"夜合花·柳暝河桥","author":"吴文英","dynasty":"宋","verses":["柳暝河桥，莺晴台苑，短策频惹春香。","当时夜泊，温柔便入深乡。","词韵窄，酒杯长。","翦蜡花、壶箭催忙。","共追游处，凌波翠陌，连棹横塘。","十年一梦凄凉。","似西湖燕去，吴馆巢荒。","重来万感，依前唤酒银罂。","溪雨急，岸花狂。","趁残鸦、飞过苍茫。","故人楼上，凭谁指与，芳草斜阳。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-82","tags":["宋词三百首","西湖"]},{"id":"poem-5a97ed766bf37684a73ffa11","title":"和张仆射塞下曲 二","author":"卢纶","dynasty":"唐","verses":["林暗草惊风，将军夜引弓。","平明寻白羽，没在石棱中。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-6d2e12c0-c1b8-4242-888c-9dba1a8f93ce","tags":["唐诗三百首","将军","乐府","边塞","赞美","狩猎"]},{"id":"poem-5a98917f4df24f58aa456aa4","title":"偈七首  其七","author":"释法泉","dynasty":"宋","verses":["非佛非心徒拟议，得皮得髓谩商量。","临行珍重诸禅侣，门外千山正夕阳。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-1ba917f0-bf20-429c-80b7-0856f1491dd1","tags":[]},{"id":"poem-5a9a4be8c6991ab4588ca86d","title":"女冠子·求仙去也","author":"薛昭蕴","dynasty":"五代","verses":["求仙去也，翠钿金篦尽舍，入崖峦。","雾卷黄罗帔，云雕白玉冠。","野烟溪洞冷，林月石桥寒。","静夜松风下，礼天坛。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-42","tags":[]},{"id":"poem-5a9b61726aaf627122d36f1c","title":"和裴司空以诗请刑部白侍郎双鹤","author":"张籍","dynasty":"唐","verses":["皎皎仙家鹤，远留闲宅中。","徘徊幽树月，嘹唳小亭风。","丞相西园好，池塘野水通。","欲将来放此，赏望与宾同。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-d8d8cce8-9094-4f66-b7ac-dc0079ecaf02","tags":[]},{"id":"poem-5a9c06413a20af34b4559d68","title":"永遇乐·秋色方浓","author":"李纲","dynasty":"宋","verses":["秋色方浓，好天凉夜，风雨初霁。","缺月如钩，微云半掩，的灿星河碎。","爽来轩户，凉生枕簟，夜永悄然无寐。","起徘徊，凭栏凝伫，片时万情千意。","江湖倦客，年来衰病，坐叹岁华空逝。","往事成尘，新愁似锁，谁是知心底。","五陵萧瑟，中原杳杳，但有满襟清泪。","烛兰缸，呼童取酒，且图径醉。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-551","tags":[]},{"id":"poem-5aaa0ec115ee6a7bf85ca007","title":"答西蜀欧阳侍郎颂（题拟）","author":"延沼","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-b090f8a7-622a-45ae-a8d1-b9010163e0e1","tags":[]},{"id":"poem-5ab2dc1b900cdfdde3eea5fe","title":"寄金州姚使君员外","author":"马戴","dynasty":"唐","verses":["老怀清净化，乞去守洵阳。","废井人应满，空林虎自藏。","迸泉疎石窦，残雨发椒香。","山缺通巴峡，江流带楚樯。","忧农生野思，祷庙结云装。","覆局松移影，听琴月堕光。","鸟鸣开郡印，僧去置禅床。","罢贡金休凿，凌寒笋更长。","退公披鹤氅，高步隔鹓行。","相见朱门内，麾幢拂曙霜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-715a9521-1779-4728-a918-065dd7d8d84c","tags":[]},{"id":"poem-5ab30d878891e3bbbe67da84","title":"使回留别襄阳李司空","author":"张籍","dynasty":"唐","verses":["江亭寒日晚，弦管有离声。","从此一筵别，独为千里行。","迟迟恋恩德，役役限公程。","回首吟新句，霜云满楚城。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-3bd50387-6d28-4394-921b-f30ee9ad37c9","tags":[]},{"id":"poem-5aba0930e17f671c9505ce40","title":"同家兄题渭南王公别业","author":"蔡希寂","dynasty":"唐","verses":["好闲知在家，退迹何必深。","不出人境外，萧条江海心。","轩车自来往，空名对清阴。","川涘将钓玉，乡亭期散金。","素晖射流濑，翠色緜森林。","曾为诗书癖，宁惟耕稼任。","吾兄许微尚，枉道来相寻。","朝庆老莱服，夕闲安道琴。","文章遥颂美，寤寐增所钦。","既郁苍生望，明时岂陆沈。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-ba63b5b7-5201-41f8-9d57-e2258a8d3d01","tags":[]},{"id":"poem-5ac0e0728a9f57fc9d7a242f","title":"智新上人话旧","author":"李洞","dynasty":"唐","verses":["蟋蟀灯前话旧游，师经几夏我经秋。","金陵市合月光里，甘露门开峰朵头。","晴眺远帆飞入海，夜禅阴火吐当楼。","相看未得东归去，满壁寒涛泻白鸥。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-d5431302-07b4-4def-b5ff-e5b1ffd70fcb","tags":[]},{"id":"poem-5ac4a75e0ee7c3a0961b3541","title":"送崔夷甫员外和蕃","author":"李嘉祐","dynasty":"唐","verses":["君过湟中去，寻源未是赊。","经春逢白草，尽日度黄沙。","双节行为伴，孤烽到似家。","和戎非用武，不学李轻车。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-0117d122-eb63-4b9c-9b0d-764719baccc1","tags":[]},{"id":"poem-5aca14c53862ec084c1f1e4c","title":"谒金门·春满院","author":"薛昭蕴","dynasty":"五代","verses":["春满院，叠损罗衣金线。","睡觉水晶帘未卷，檐前双语燕。","斜掩金铺一扇，满地落花千片。","早是相思肠欲断，忍教频梦见。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-44","tags":[]},{"id":"poem-5ad67ed01a6e790b9e21b981","title":"闲居寄陈山人","author":"谭用之","dynasty":"宋","verses":["闲居何处得闲名，坐掩衡茅损性灵。","破梦晓钟闻竹寺，沁心秋雨浸莎庭。","瓮边难负千杯绿，海上终眠万仞青。","珍重先生全太古，应看名利似浮云。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-7a650ab2-c09f-4573-9bb9-febc1173b0ff","tags":[]},{"id":"poem-5ad6bffb92c58ad56b1aa805","title":"偈七首  其五","author":"释法泉","dynasty":"宋","verses":["文殊笑，普贤嗔，眼里无筋一世贫。","相逢尽道休官去，林下何曾见一人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-86370e4f-6861-45dd-afea-92aa18f188ab","tags":[]},{"id":"poem-5ada8f89118b90c0f1fc7913","title":"粉蝶儿","author":"施惠《幽闺记》","dynasty":"元","verses":["(小生上)山寨鸣金，白鹤半空展翅。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2960","tags":[]},{"id":"poem-5adec0935efa53b85518f51f","title":"句  其八","author":"释延寿","dynasty":"宋","verses":["草浓春径狭，树密晚窗阴。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-b8a4765c-84d3-4c6e-898a-a84629daa87d","tags":[]},{"id":"poem-5ae10031ad2b8e170eb6a112","title":"乱后入洪州西山","author":"曹松","dynasty":"唐","verses":["寂寂阴溪水漱苔，尘中将得苦吟来。","东峰道士如相问，县令而今不姓梅。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-440c408d-c86d-4e0c-8526-99eb7c6429d0","tags":[]},{"id":"poem-5aebfcbbe45aaca402b2824f","title":"诸季招客游东山置酒赋诗以病不果往次其韵","author":"李纲","dynasty":"宋","verses":["衰病年来百事阑，禅居环绕尽青山。","登髙选胜从君乐，隐几忘言输我闲。","一枕清风销永日，三杯浊酒发酡颜。","雀罗可设从来事，东阁常开不是悭。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-77346bf3-e449-49d3-9828-dbec343832dc","tags":[]},{"id":"poem-5af2bc4c9341933946422a31","title":"赠泰州掾令狐克己","author":"徐铉","dynasty":"宋","verses":["念子才多命且奇，乱中抛掷少年时。","深藏七泽衣如雪，却见中朝鬓似丝。","旧德在人终远大，扁舟为吏莫推辞。","孤芳自爱凌霜处，咏取文公白菊诗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-fb3d8ae1-6321-4fef-901b-780631ab9787","tags":[]},{"id":"poem-5afa30221a0b088a979ff069","title":"两仪殿赋柏梁体","author":"太宗皇帝","dynasty":"唐","verses":["绝域降附天下平，八表无事悦圣情。","云披雾敛天地明，登封日观禅云亭。","太常具礼方告成。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-bf2685a1-fc35-4238-87ee-9f27fd58432a","tags":[]},{"id":"poem-5affc2547639e84661b579b2","title":"别俞君任通判三首  其三","author":"陈造","dynasty":"宋","verses":["房陵望毗陵，计舍六十余。","今我从远役，羡君方逸居。","逸劳不足道，会合嗟愈疎。","向来江南北，二年能几书。","残山賸水地，诗题当不虚。","得句茹不吐，思君定愁予。","溯江日千里，岂无红尾鱼。","交情傥未忘，与问今何如。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-5a4593e6-0dff-432d-8499-005e1ae1e9d6","tags":[]},{"id":"poem-5b0e65089bd0ad46b29865b6","title":"玉蝴蝶·霞帔云发","author":"温庭筠","dynasty":"唐","verses":["秋风凄切伤离，行客未归时。","塞外草先衰江，南雁到迟。","芙蓉凋嫩脸，杨柳堕新眉。","摇落使人悲，断肠谁得知。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-49","tags":[]},{"id":"poem-5b0ff5656140059a3d59d4aa","title":"泣姜贫乐谢长兴长赵可斋  其二","author":"释居简","dynasty":"宋","verses":["金尽骅骝死，交游散似云。","五穷逐不去，百拙巧难分。","竹唁梅疎友，鸥随鹭吊群。","未铭先传散，勒徧霅川𣸣。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-8873792c-c933-402e-b481-de0c58be44a9","tags":[]},{"id":"poem-5b1ae31c8a26eecf02c5a8a3","title":"君子阳阳","author":"佚名","dynasty":"先秦","verses":["君子阳阳，左执簧，右招我由房，其乐只且！","君子陶陶，左执翿，右招我由敖，其乐只且！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-66","tags":[]},{"id":"poem-5b1cceb9c9b08cef9d7eeb8c","title":"春宵","author":"苏轼","dynasty":"宋","verses":["春宵一刻值千金，花有清香月有阴。","歌管楼台声细细，秋千院落夜沈沈。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-春宵","tags":[]},{"id":"poem-5b270176a4292d2bcffa9b14","title":"浪淘沙·啼魄一天涯","author":"高观国","dynasty":"宋","verses":["啼魄一天涯。","怨入芳华。","可怜零血染烟霞。","记得西风秋露冷，曾浼司花。","明月满窗纱。","倦客思家。","故宫春事与愁赊。","冉冉断魂招不得，翠冷红斜。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-415","tags":[]},{"id":"poem-5b2cf58c66c91204dea219b2","title":"逢老人","author":"隐峦","dynasty":"唐","verses":["路逢一老翁，两鬓白如雪。","一里二里行，四回五回歇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-ba9b0630-2932-4e64-afad-366367d9201f","tags":[]},{"id":"poem-5b3af9ab296f590b0787e981","title":"东平路作三首 一","author":"高适","dynasty":"唐","verses":["南图适不就，东走岂吾心。","索索凉风动，行行秋水深。","蝉鸣木叶落，兹夕更愁霖。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-781223c9-12d7-42f1-8a53-273d4a032a11","tags":[]},{"id":"poem-5b3b94e6e9f81830300442ac","title":"满江红·访雨寻云","author":"柳永","dynasty":"宋","verses":["访雨寻云，无非是、奇容艳色。","就中有、天真妖丽，自然标格。","恶发姿颜欢喜面，细追想处皆堪惜。","自别后、幽怨与闲愁，成堆积。","鳞鸿阻，无信息。","梦魂断，难寻觅。","尽思量，休又怎生休得。","谁恁多情凭向道，纵来相见且相忆。","便不成、常遣似如今，轻抛掷。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-193","tags":[]},{"id":"poem-5b501964d267059ae73efcaa","title":"郊庙歌辞 禅社首乐章 太和","author":"贺知章、源乾曜","dynasty":"唐","verses":["昭昭有唐，天俾万国。","列祖应命，四宗顺则。","申锡无疆，宗我同德。","曾孙继序，享神配极。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-ab812eee-9ec2-43c1-8f1e-98ccbe583ede","tags":[]},{"id":"poem-5b53b65152f93705c75739ec","title":"玉团儿·晓来一阵金风劣","author":"张镃","dynasty":"宋","verses":["晓来一阵金风劣。","把阆海、檀霞细屑。","依就花儿，深藏叶底，不教人折。","初开数朵谁知得。","却又是、金风漏泄。","吹起清芬，露成香露，月成香月。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-343","tags":[]},{"id":"poem-5b5ae428c4df72c07a3ff661","title":"句 三","author":"罗隐","dynasty":"唐","verses":["桃李无言应笑我，二年尘土满渔航。","（《五色线》。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-751349f5-6ec5-4fff-bc1a-3b93888febec","tags":[]},{"id":"poem-5b5d4a30d2838cf8d445b4cb","title":"渭城曲","author":"王维","dynasty":"唐","verses":["渭城朝雨浥轻尘，客舍青青杨柳春。","劝君更尽一杯酒，西出阳关无故人。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-1575c835-1241-4d7b-99dc-6d700549ac65","tags":["八年级下册(课外)","友情","小学古诗","送别","初中古诗","乐府","唐诗三百首","近代曲辞","四年级上册"]},{"id":"poem-5b637b818ca261ba1a45c281","title":"吊元鲁山 八","author":"孟郊","dynasty":"唐","verses":["当今富教化，元后得贤相。","冰心镜衰古，霜议清遐障。","幽埋尽洸洗，滞旅免流浪。","唯余鲁山名，未获旌廉让。","二三贞苦士，刷视耸危望。","发秋青山夜，目断丹阙亮。","诱类幸从兹，嘉招固非妄。","小生奏狂狷，感惕增万状。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-684108f3-6a6e-4052-a45f-12ad2f72b64c","tags":[]},{"id":"poem-5b664c2f84cd705fda0e3b70","title":"上巳","author":"杨凝","dynasty":"唐","verses":["帝京元巳足繁华，细管清弦七贵家。","此日风光谁不共，纷纷皆是掖垣花。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-82b82749-a034-4ad1-97d2-ed361b75885c","tags":[]},{"id":"poem-5b81cb82dfd4b4a92363d8d4","title":"中峰亭","author":"朱景玄","dynasty":"唐","verses":["中峰上翠微，窗晓早霞飞。","几引登山屐，春风踏雪归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-51ad6094-adc2-4a1d-b5cd-986bb04e2032","tags":[]},{"id":"poem-5b902bbb73e5c74db2b4ea06","title":"赠徐山人","author":"李洞","dynasty":"唐","verses":["徐生何代降坤维，曾伴园公采紫芝。","瓦砾变黄忧世换，髭须放白怕人疑。","山房古竹麄于树，海岛灵童寿等龟。","知叹有唐三百载，光阴未抵一先棋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-5db6190c-5a02-426f-882e-68c044218069","tags":[]},{"id":"poem-5b90c8b592f07ea245c64e13","title":"灌花","author":"柴元彪","dynasty":"宋","verses":["小圃辛勤植众芳，年年雨露借恩光。","近来天意高难问，抱瓮从朝到夕阳。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-f21132c1-d717-46b6-9fbd-553a2a9c7012","tags":[]},{"id":"poem-5b91d8b8cbab59bc01d00f9d","title":"薄幸·艳真多态","author":"贺铸","dynasty":"宋","verses":["艳真多态。","更的的，频回眄睐。","便认得、琴心相许，与写宜男双带。","记画堂、斜月朦胧，轻颦微笑娇无奈。","便翡翠屏开，芙蓉帐掩，与把香罗偷解。","自过了收灯后，都不见、踏青挑菜。","几回凭双燕，丁宁深意，往来翻恨重帘碍。","约何时再。","正春浓酒暖，人闲昼永无聊赖。","厌厌睡起，犹有花梢日在。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-75","tags":["宋词三百首"]},{"id":"poem-5b953c2d49774a9a2e7069dd","title":"御街行·纷纷堕叶飘香砌","author":"范仲淹","dynasty":"宋","verses":["纷纷堕叶飘香砌。","夜寂静、寒声碎。","真珠帘卷玉楼空，天淡银河垂地。","年年今夜，月华如练，长是人千里。","愁肠已断无由醉。","酒未到、先成泪。","残灯明灭枕头欹。","谙尽孤眠滋味。","都来此事，眉间心上，无计相回避。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-140","tags":["宋词三百首"]},{"id":"poem-5b973a74daa3936431ac6444","title":"小重山·醉倚朱阑一解衣","author":"米友仁","dynasty":"宋","verses":["醉倚朱阑一解衣。","碧云迷望眼，断虹低。","近来休说带宽围。","人千里，还是燕双飞。","深院日初迟。","绮窗帘幕静，恨生眉。","不堪虚度是花时。","鸿来速，争解寄相思。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-48","tags":[]},{"id":"poem-5ba68cfb89da1b6e8d10464d","title":"民劳","author":"佚名","dynasty":"先秦","verses":["民亦劳止，汔可小康。惠此中国，以绥四方。无纵诡随，以谨无良。","式遏寇虐，憯不畏明。柔远能迩，以定我王。","民亦劳止，汔可小休。惠此中国，以为民逑。无纵诡随，以谨惛怓。","式遏寇虐，无俾民忧。无弃尔劳，以为王休。","民亦劳止，汔可小息。惠此京师，以绥四国。无纵诡随，以谨罔极。","式遏寇虐，无俾作慝。敬慎威仪，以近有德。","民亦劳止，汔可小愒。惠此中国，俾民忧泄。无纵诡随，以谨丑厉。","式遏寇虐，无俾正败。戎虽小子，而式弘大。","民亦劳止，汔可小安。惠此中国，国无有残。无纵诡随，以谨缱绻。","式遏寇虐，无俾正反。王欲玉女，是用大谏。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-252","tags":[]},{"id":"poem-5babf8973ae0333f51323ac1","title":"清平乐·银河秋浪","author":"毛滂","dynasty":"宋","verses":["银河秋浪。","遥出昆仑上。","忽变澄澜添碧涨。","可道升平无象。","黄云浊雾初开。","荣光休气徘徊。","试觅当时五老，金泥玉检将来。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-709","tags":[]},{"id":"poem-5bb7e0aaf6ae4696ef168208","title":"叶进卿寄和章次韵复之","author":"陈造","dynasty":"宋","verses":["君文如泛涛渊里，方快惊澜忽清泚。","手抄口诵欲忘年，小窗长日铜炉烟。","端宜饮我三斗墨，有底向人矜此客。","平生歌颂仍歌风，宽柔静直能形容。","心知公瑾胜醇酒，人仰韩公真北斗。","词坛正倚君主盟，笔驱化工钩物情。","诗来得我玩世意，刻石便当幽居记。","儿曹转手作云雨，陈雷输心可人否。","中牟报政径青云，此老洗眼久徯君。","重逢首理车笠语，定指渠侬笑城府。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-88bf31fc-2edd-4366-b609-8b81a117a6c8","tags":[]},{"id":"poem-5bbbed75b6a1e2d2b8ed456a","title":"哀时命","author":"庄忌","dynasty":"汉","verses":["哀时命之不及古人兮，夫何予生之不遘时！","往者不可扳援兮，徕者不可与期。","志憾恨而不逞兮，杼中情而属诗。","夜炯炯而不寐兮，怀隐忧而历兹。","心郁郁而无告兮，众孰可与深谋！","欿愁悴而委惰兮，老冉冉而逮之。","居处愁以隐约兮，志沉抑而不扬。","道壅塞而不通兮，江河广而无梁。","愿至昆仑之悬圃兮，采锺山之玉英。","揽瑶木之橝枝兮，望阆风之板桐。","弱水汩其为难兮，路中断而不通。","势不能凌波以径度兮，又无羽翼而高翔。","然隐悯而不达兮，独徙倚而彷徉。","怅惝罔以永思兮，心纡轸而增伤。","倚踌躇以淹留兮，日饥馑而绝粮。","廓抱景而独倚兮，超永思乎故乡。","廓落寂而无友兮，谁可与玩此遗芳？","白日晼晼其将入兮，哀余寿之弗将。","车既弊而马罢兮，蹇邅徊而不能行。","身既不容于浊世兮，不知进退之宜当。","冠崔嵬而切云兮，剑淋离而从横。","衣摄叶以储与兮，左袪挂于榑桑。","右衽拂于不周兮，六合不足以肆行。","上同凿枘于伏戏兮，下合矩矱于虞唐。","原尊节而式高兮，志犹卑夫禹汤。","虽知困其不改操兮，终不以邪枉害方。","世并举而好朋兮，壹斗斛而相量。","众比周以肩迫兮，贤者远而隐藏。","为凤皇作鹑笼兮，虽翕翅其不容。","灵皇其不寤知兮，焉陈词而效忠。","俗嫉妒而蔽贤兮，孰知余之从容？","愿舒志而抽冯兮，庸讵知其吉凶？","璋珪杂于甑窐兮，陇廉与孟娵同宫。","举世以为恒俗兮，固将愁苦而终穷。","幽独转而不寐兮，惟烦懑而盈匈。","魂眇眇而驰骋兮，心烦冤之忡忡。","志欿憾而不憺兮，路幽昧而甚难。","块独守此曲隅兮，然欿切而永叹。","愁修夜而宛转兮，气涫沸其若波。","握剞劂而不用兮，操规矩而无所施。","骋骐骥于中庭兮，焉能极夫远道？","置援狖于棂槛兮，夫何以责其捷巧？","驷跛鳖而上山兮，吾固知其不能升。","释管晏而任臧获兮，何权衡之能称？","箟簬杂于黀蒸兮，机蓬矢以射革。","负檐荷以丈尺兮，欲伸要而不可得。","外迫胁于机臂兮，上牵联于矰隿。","肩倾侧而不容兮，固陿腹而不得息。","务光自投于深渊兮，不获世之尘垢。","孰魁摧之可久兮，愿退身而穷处。","凿山楹而为室兮，下被衣于水渚。","雾露蒙蒙其晨降兮，云依斐而承宇。","虹霓纷其朝霞兮，夕淫淫而淋雨。","怊茫茫而无归兮，怅远望此旷野。","下垂钓于溪谷兮，上要求于仙者。","与赤松而结友兮，比王侨而为耦。","使枭杨先导兮，白虎为之前后。","浮云雾而入冥兮，骑白鹿而容与。","魂眐眐以寄独兮，汨徂往而不归。","处卓卓而日远兮，志浩荡而伤怀。","鸾凤翔于苍云兮，故矰缴而不能加。","蛟龙潜于旋渊兮，身不挂于罔罗。","知贪饵而近死兮，不如下游乎清波。","宁幽隐以远祸兮，孰侵辱之可为。","子胥死而成义兮，屈原沉于汨罗。","虽体解其不变兮，岂忠信之可化。","志怦怦而内直兮，履绳墨而不颇。","执权衡而无私兮，称轻重而不差。","摡尘垢之枉攘兮，除秽累而反真。","形体白而质素兮，中皎洁而淑清。","时猒饫而不用兮，且隐伏而远身。","聊窜端而匿迹兮，嗼寂默而无声。","独便悁而烦毒兮，焉发愤而筊抒。","时暧暧其将罢兮，遂闷叹而无名。","伯夷死于首阳兮，卒夭隐而不荣。","太公不遇文王兮，身至死而不得逞。","怀瑶象而佩琼兮，愿陈列而无正。","生天坠之若过兮，忽烂漫而无成。","邪气袭余之形体兮，疾憯怛而萌生。","原壹见阳春之白日兮，恐不终乎永年。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-37","tags":[]},{"id":"poem-5bbc7a4d18591be5639b6c9d","title":"游长宁公主流杯池二十五首 十四","author":"上官昭容","dynasty":"唐","verses":["攀藤招逸客，偃桂协幽情。","水中看树影，风里听松声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-75cab210-6be6-4de7-905e-4ca56e574ac5","tags":[]},{"id":"poem-5bc1274e5178fe257eadbab6","title":"兴京陪祭福陵","author":"纳兰性德","dynasty":"清","verses":["龙盘凤翥气佳哉，东指斋宫玉辇来。","影入松楸仙仗远，香升俎豆晓云开。","盛仪备处千官肃，神贶乘时万马回。","豹尾叨陪须献颂，小臣惭愧展微才。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-244","tags":[]},{"id":"poem-5bceb04d4e8ca01afc58b8b9","title":"赛神曲","author":"王建","dynasty":"唐","verses":["男抱琵琶女作舞，主人再拜听神语。","新妇上酒勿辞勤，使尔舅姑无所苦。","椒浆湛湛桂座新，一双长箭系红巾。","但愿牛羊满家宅，十月报赛南山神。","青天无风水复碧，龙马上鞍牛服轭。","纷纷醉舞踏衣裳，把酒路旁劝行客。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-676c6fd4-203d-47e3-8aea-00e2a34d96ea","tags":[]},{"id":"poem-5bd41ea5112ae1e6dbff46ee","title":"山居诗  其五六","author":"释延寿","dynasty":"宋","verses":["野景陶情皆得意，凡夫举目尽堪愁。","秦川几度埋番骨，棘路还曾耸玉楼。","幻体不知波上沫，狂心须认镜中头。","浮生役役贪荣者，求到真空卒未休。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-43d841c7-7b80-4cf4-b530-05e95ed4b9e0","tags":[]},{"id":"poem-5be09df270a11b024409e1a6","title":"西溪子·捍拨双盘金凤","author":"牛峤","dynasty":"五代","verses":["捍拨双盘金凤，蝉鬓玉钗摇动。","画堂前，人不语，弦解语。","弹到《昭君怨》处，翠蛾愁，不抬头。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-24","tags":[]},{"id":"poem-5be9e0f346495d1af02958f5","title":"登楼歌","author":"王维","dynasty":"唐","verses":["聊上君兮高楼，飞甍鳞次兮在下。","俯十二兮通衢，绿槐参差兮车马。","却瞻兮龙首，前眺兮宜春。","王畿郁兮千里，山河壮兮咸秦。","舍人下兮青宫，据胡床兮书空。","执戟疲于下位，老夫好隐兮墙东。","亦幸有张伯英草圣兮龙腾蚪跃，摆长云兮捩回风。","琥珀酒兮雕胡饭，君不御兮日将晚。","秋风兮吹衣，夕鸟兮争返。","孤砧发兮东城，林薄暮兮蝉声远。","时不可兮再得，君何为兮偃蹇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-2eff02ed-d245-4c86-bc91-6f67a72ac95c","tags":[]},{"id":"poem-5bec2ed7b6f430714a136a9b","title":"登岘亭","author":"司空曙","dynasty":"唐","verses":["岘山回首望秦关，南向荆州几日还。","今日登临唯有泪，不知风景在何山。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-844a6888-158d-4ffd-9b8f-89fce8d79c9f","tags":[]},{"id":"poem-5bec8a82b156fe68b48a71cb","title":"夏日","author":"张文潜","dynasty":"宋","verses":["长夏江村风日清，檐牙燕雀已生成。","蝶衣晒粉花枝午，蛛网添丝屋角晴。","落落疏廉邀月影，嘈嘈虚枕纳溪声。","久斑两鬓如霜雪，直欲樵渔过此生。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-夏日","tags":[]},{"id":"poem-5bed9dce5f70a4f5a72c13e1","title":"横吹曲辞 折杨柳","author":"刘宪","dynasty":"唐","verses":["沙塞三河道，金闺二月春。","碧烟杨柳色，红粉绮罗人。","露叶怜啼脸，风花思舞巾。","攀持君不见，为听曲中新。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-35c4618c-3896-45f8-9b24-51764c90383f","tags":[]},{"id":"poem-5bf8015a68174e576a6f0b1c","title":"三月海棠","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(净上)年老人，登山涉水多劳顿，送孩儿知他认也不认？伤情！母在家中思儿苦，怎知儿在此没投奔？我移步趱行程，无言不觉泪沾襟。","老汉蒙李三娘着我送孩儿到并州太原府去还刘大郎。","一路辛苦，来到这里。","夜来在客店中安歇了一宵，感得店主娘与孩儿吃一夜乳。","如今想孩儿肚又饥，这里是酒店，想有妇人，再问他买些与他吃。","多少是好？(净、丑见介。","丑)公公那处来？莫不是买酒吃？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8941","tags":[]},{"id":"poem-5bfcc6ba62c9fab0a1472502","title":"叶梦授送家园梅花且以绝句十五章见示次其韵  其四","author":"李纲","dynasty":"宋","verses":["慇懃剩作送梅诗，撚断霜髭不为棋。","只恐苦吟令太瘦，个中风味有谁知。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-bd69a5a8-d94b-4782-8f45-a93d8492ff83","tags":[]},{"id":"poem-5bff4b8064057c0841498087","title":"送宋左曹得温州  其一","author":"释居简","dynasty":"宋","verses":["翁居藩辅久，叔年又相先。","万石不足数，一灯无别传。","家声青琐闼，风味赤城仙。","好是猿啼处，霞标最近天。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-d73812f2-8e05-4e47-8ca3-f96421d0e3a6","tags":[]},{"id":"poem-5c02dd4ae022ff33ab28ba47","title":"感恩多·两条红粉泪","author":"牛峤","dynasty":"五代","verses":["两条红粉泪，多少香闺意。","强攀桃李枝，敛愁眉。","陌上莺啼蝶舞，柳花飞。","柳花飞，愿得郎心，忆家还早归。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-6","tags":[]},{"id":"poem-5c17e16a73a500ce0a05f35d","title":"司徒开府韩国富公挽辞四首  其三","author":"司马光","dynasty":"宋","verses":["大吕功名重，鸿毛轩冕轻。","闲居客愈盛，暂出市皆倾。","溟海涵容大，龙门谒见荣。","谦光俨在目，恸哭望佳城。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-a6f5f984-8c79-4b06-a9cc-374f46483762","tags":[]},{"id":"poem-5c188813dc0f85d8b8ea04cc","title":"满江红·暮雨萧萧","author":"洪适","dynasty":"宋","verses":["暮雨萧萧，飞败叶、增添秋色。","登高会、痴风吹散，山居佳客。","人世难逢开口笑，老来便觉流年迫。","到如今、黄菊满园开，无人摘。","珠履凑，铢衣窄。","萦翠袖，催牙拍。","索松儿添半，战酣相吓。","橘绿橙黄时节好，舞停歌罢门墙隔。","酒醒时、枕上一声鸡，东方白。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-734","tags":[]},{"id":"poem-5c1d37e9d5d86b33997182af","title":"题山桥十首  其一","author":"王柏","dynasty":"宋","verses":["轧轧飞车入翠微，人于妙处未深知。","自从标榜新拈掇，碎却山桥一段奇。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-bb697a9f-6d97-45bd-835e-3387ee0f0a1a","tags":[]},{"id":"poem-5c2486aa6d4564b214a00540","title":"有駜","author":"佚名","dynasty":"先秦","verses":["有駜有駜，駜彼乘黄。夙夜在公，在公明明。振振鹭，鹭于下。鼓咽咽，醉言舞。于胥乐兮！","有駜有駜，駜彼乘牡。夙夜在公，在公饮酒。振振鹭，鹭于飞。鼓咽咽，醉言归。于胥乐兮！","有駜有駜，駜彼乘駽。夙夜在公，在公载燕。自今以始，岁其有。君子有谷，诒孙子。于胥乐兮！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-297","tags":[]},{"id":"poem-5c35f7a87becb2f19de44987","title":"去秋行","author":"杜甫","dynasty":"唐","verses":["去秋涪江木落时，臂枪走马谁家儿。","到今不知白骨处，部曲有去皆无归。","遂州城中汉节在，遂州城外巴人稀。","战场冤魂每夜哭，空令野营猛士悲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-21f7f097-466f-4f6a-b76f-96d443de7109","tags":[]},{"id":"poem-5c3c8b50db0e13e4d5a164be","title":"邵伯阻风小泊赠送行诸公","author":"陈造","dynasty":"宋","verses":["长征每爱日，小泊未遻意。","阴风自南北，客子听轩轾。","召棠望吾乡，不作秦越异。","船阁鴈鹜洲，人穿鱼虾市。","相逢各吴语，知识十三四。","水实不自买，海错有佳馈。","饯行余十客，超俗见友义。","笑谭寒谷春，为我洗羁思。","相与卧玉瓶，跋烛得微醉。","老怀易作恶，别语毋动喙。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-78d3cc10-56c2-467f-a63c-a23ccd8285c1","tags":[]},{"id":"poem-5c40839b487b3886175b631b","title":"荷叶铺水面·春光艳冶","author":"康与之","dynasty":"宋","verses":["春光艳冶，游人踏绿苔。","千红万紫竞香开。","暖风拂鼻籁，蓦地暗香透满怀。","荼縻似锦裁。","娇红间绿白，只怕迅速春回。","误落在尘埃。","折向鬓云间、金凤钗。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-325","tags":[]},{"id":"poem-5c44857e8eef7d8466609559","title":"绣带儿","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["亲年老光阴有儿？行孝正是今日。","终不然为着一领蓝袍，却落后了戏彩斑衣。","思之，此行荣贵虽可拟，怕亲老等不得荣贵。","(外唱)春闱里纷纷大儒，难道是没爹娘的孩儿方去？(末唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4934","tags":[]},{"id":"poem-5c4507f39630487ea9b0f5f4","title":"辋川集 竹里馆","author":"王维","dynasty":"唐","verses":["独坐幽篁里，弹琴复长啸。","深林人不知，明月来相照。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-36e09cb4-4fb7-48be-b6c6-c9bd906d9331","tags":["唐诗三百首","孤独","生活","初中古诗","月亮","归隐","五言绝句","七年级下册(课外)"]},{"id":"poem-5c45daeabf3c04bcba35bdd0","title":"喜雨偈  其一","author":"释了思","dynasty":"宋","verses":["熇熇炎威遍野飘，流金烁石土山焦。","精诚不作轩雷转，孰与人间济槁苗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-4338d65b-7925-4ed6-a64a-ccaea468baba","tags":[]},{"id":"poem-5c48bc1178843b392da09948","title":"偶然作六首 五","author":"王维","dynasty":"唐","verses":["赵女弹箜篌，复能邯郸舞。","夫壻轻薄儿，鬬鸡事齐主。","黄金买歌笑，用钱不复数。","许史相经过，高门盈四牡。","客舍有儒生，昂藏出邹鲁。","读书三十年，腰间无尺组。","被服圣人教，一生自穷苦。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-4811841a-3063-4975-8f52-1420de15563a","tags":[]},{"id":"poem-5c565848223e5837d14e4886","title":"题李将军山亭","author":"郭良","dynasty":"唐","verses":["凤辖将军位，龙门司隶家。","衣冠为隐逸，山水作繁华。","径出重林草，池摇两岸花。","谁知贵公第，亭院有烟霞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-ee36aa5a-c3d0-4875-8ff8-e1807a7ce622","tags":[]},{"id":"poem-5c596cfcf62604231e69f95f","title":"伏读三月六日内禅诏书及传将士牓檄慨王室之艰危悯生灵之涂炭悼前策之不从恨奸回之误国感愤有作聊以述怀四首  其三","author":"李纲","dynasty":"宋","verses":["叹息奸臣术已疏，谋身误国竟何如。","马嵬不进杨钊死，关陜初临元振除。","王室威灵嗟索寞，苍生环堵未安居。","荒陬不见中原事，望断东吴一纸书。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-d184cc59-4ada-4cd8-b6d8-94793f21a26c","tags":[]},{"id":"poem-5c6f0ea454293fa48cf65dd1","title":"观邻老栽松","author":"李端","dynasty":"唐","verses":["虽过老人宅，不解老人心。","何事残阳里，栽松欲待阴。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-7a9e58d6-e9a2-4b7a-87b1-25f114878049","tags":[]},{"id":"poem-5c7aaeabdbd9a58d1c3b3393","title":"次韵士特试谷帘泉见怀之作  其一","author":"李纲","dynasty":"宋","verses":["桑苎尝来第二泉，翠松偃盖色相鲜。","谷帘窦乳争多少，西子南威各自妍。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-6f17e4a3-5d41-4802-ac01-f42ae66dbeab","tags":[]},{"id":"poem-5c7fac57065fb2187bd43181","title":"苦热寄赤松道者","author":"贯休","dynasty":"唐","verses":["天云如烧人如炙，天地𬬻中更合适。","蝉喘雷干冰井融，些子清风有何益。","守羊真人聃之役，高吟招隐倚碧壁。","紫气红烟鲜的的，涧茗园瓜曲尘色，骄冷奢凉合相忆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-49338a72-6850-4da6-9d4c-ed9760ecb164","tags":[]},{"id":"poem-5c83f97cfda61e12190988d2","title":"河渎神·江上草芊芊","author":"孙光宪","dynasty":"五代","verses":["江上草芊芊，春晚湘妃庙前。","一方卵色楚南天，数行征雁联翩。","独倚朱栏情不极，魂断终朝相忆。","两桨不知消息，远汀时起㶉𫛶。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-6","tags":[]},{"id":"poem-5c86befff6427c4273e942b0","title":"盐井","author":"杜甫","dynasty":"唐","verses":["卤中草木白，青者官盐烟。","官作既有程，煮盐烟在川。","汲井岁榾榾，出车日连连。","自公斗三百，转致斛六千。","君子慎止足，小人苦喧阗。","我何良叹嗟，物理固自然。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-e19f6e14-e964-4d21-a5c7-e9e1a607ed16","tags":[]},{"id":"poem-5c8f4ce8ecdc4b3c0242b3d8","title":"菩萨蛮·夜深不至春蟾见","author":"张先","dynasty":"宋","verses":["夜深不至春蟾见。","令人更更情飞乱。","翠幕动风亭。","时疑响屉声。","花香闻水榭。","几误飘衣麝。","不忍下朱扉。","绕廊重待伊。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-268","tags":[]},{"id":"poem-5c90b848288afa6b2fa60916","title":"株林","author":"佚名","dynasty":"先秦","verses":["胡为乎株林？从夏南！匪适株林，从夏南！","驾我乘马，说于株野。乘我乘驹，朝食于株！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-143","tags":[]},{"id":"poem-5c9383640928626b199ae09e","title":"偈颂（幷序○序为南岳齐己撰） 三十一","author":"居遁","dynasty":"唐","verses":["道者（《传灯录》作「学道」）无端学画龙，元来未得笔头踪。","一朝体得真龙后，始觉平生（《传灯录》作「方觉从前」）枉用功。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-4a4e6c72-8662-41bf-b867-5a6ccfecdb9f","tags":["衡山"]},{"id":"poem-5c9b3cba8c8f5c697bb93c29","title":"环珠洞","author":"吕愿中","dynasty":"宋","verses":["朝野乐升平，园林穷胜讨。","快雨洗尘埃，秋山浄如埽。","游鱼聚江湾，饥乌集木杪。","群芳鬰峥嵘，一水翠缭绕。","云头苍狗变，龙蛇乱夭矫。","岩洞真奇崛，造物逞天巧。","近在堂奥间，超然类三岛。","暂舍簿书忙，何时脱纷扰。","静听黄鹂鸣，一声还复悄。","𫄥维去咫尺，涉步即幽窈。","新岸暗苍苔，乔木蔽萝茑。","山腹有遗祠，隐然见华表。","笋舆访崇台，空旷游遐眺。","八桂困樵苏，叹息心为愀。","任侯三蜀秀，冰壶湛春晓。","有药驻朱颜，可以长不老。","雄篇顷刻成，举座悉称好。","戛玉副鸣球，士夫善传道。","五岭类观东，一览众山小。","吕岩何兴废，事固有前兆。","新诗刻翠珉，异日可稽考。","玩珠纪胜游，聊复醉清醥。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-0be9afc2-63b6-4525-94fd-e1520ef20a82","tags":[]},{"id":"poem-5c9cab3fd4bc2ab0c43fa4dc","title":"敍诗","author":"张祜","dynasty":"唐","verses":["二雅泄诗源，滂滂接涟漪。","宣尼昔道{卄/氵史}，豁豁无阻疑。","小开作泾港，大涨为塘陂。","可令万顷澄，可使百派支。","生民苟灌溉，九谷长蕃滋。","何意束晳徒，《补亡》辄继之。","安知去圣远，立旨无乖隳。","五言起李陵，其什伤远离。","雄材耻小用，属咏隅成规。","后时班婕妤，团扇托忧悲。","枚情既云妙，蔡韵肯容卑。","建安陈思王，龙变五不知。","刘桢骨气真，王粲文质奇。","阮公先兴亡，陆氏以才推。","雅怨止潘子，高摽存左思。","延年得殊致，灵运拔英姿。","沈侯美玉蕴，谢守文锦摛。","江词骋奇妙，鲍趣出孤危。","飘飘喜泽翁，于在务脱遗。","陈隋后诸子，往往沙可披。","拾遗昔陈公，强立制颓萎。","英华自沈宋，律唱{牙丿=丶}相维。","其间岂无长，声病为深宜。","江宁王昌齢，名贵人可垂。","波澜到李杜，碧海东弥弥。","曲江兼在才，善奏珠累累。","四面近刘复，远与何相追。","迩来韦苏州，气韵甚怡怡。","伶伦管尚在，此律谁能吹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-4ab4bfb6-37db-4014-8487-53bfe55e15e1","tags":[]},{"id":"poem-5c9e5173dcfccbd92c744659","title":"哭丘长史","author":"张籍","dynasty":"唐","verses":["丘公已殁故人稀，欲过街西更访谁。","每到子城东路上，忆君相逐入朝时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-1708826e-98b4-46c1-b549-e7fef08b274a","tags":[]},{"id":"poem-5c9e7b5f0e9e13864ce12992","title":"维天之命","author":"佚名","dynasty":"先秦","verses":["维天之命，于穆不已。于乎不显，文王之德之纯。假以溢我，我其收之。骏惠我文王，曾孙笃之。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-266","tags":[]},{"id":"poem-5c9fd67af6d7f7301b7dcb09","title":"寻陆鸿渐不遇","author":"皎然","dynasty":"唐","verses":["移家虽带郭，野径入桑麻。","近种篱边菊，秋来未著花。","扣门无犬吠，欲去问西家。","报道山中去，归时每日斜。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-565d931a-ff49-4f37-b633-524b48c2f4f0","tags":["唐诗三百首","隐士","访友","生活","五言律诗"]},{"id":"poem-5ca3497eb1cefda4beae066a","title":"浣溪沙·云外遥山是翠眉","author":"向子𬤇","dynasty":"宋","verses":["云外遥山是翠眉。","风前杨柳入腰肢。","凌波微步袜尘飞。","倚醉传歌留客处，佯嗔不语𣨼人时。","风流态度百般宜。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-802","tags":[]},{"id":"poem-5ca41214223d42742edc7c98","title":"夜直","author":"子兰","dynasty":"唐","verses":["大内隔重墙，多闻乐未央。","灯明宫树色，茶煮禁泉香。","凤辇通门静，鸡歌入漏长。","宴荣陪御席，话密近龙章。","吟步彤庭月，眠分玉暑凉。","欲粘朱绂重，频草白麻忙。","笔力将群吏，人情在致唐。","万方瞻仰处，晨夕面吾皇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-68dcd1e9-0321-4e45-8ac4-fee2694683a7","tags":[]},{"id":"poem-5ca6867c1e01ef61ee3580c5","title":"菊","author":"吕从庆","dynasty":"唐","verses":["短篱偎曲径，风雨困秋曦。","竞惜芙蓉冷，何知更有伊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-be8cf80d-9408-4ec8-aeae-76a37ec1b620","tags":[]},{"id":"poem-5cb2bde0896bf4ce403a6121","title":"汉武帝思李夫人","author":"曹唐","dynasty":"唐","verses":["惆怅冰颜不复归，晚秋黄叶满天飞。","迎风细荇传香粉，隔水残霞见画衣。","白玉帐寒鸳梦绝，紫阳宫远雁书稀。","夜深池上兰桡歇，断续歌声彻太微。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-16b38c69-8483-4e41-b359-ceadd408aeb1","tags":[]},{"id":"poem-5cb87894591c7d3d144f04e5","title":"浪淘沙·把酒祝东风","author":"欧阳修","dynasty":"宋","verses":["把酒祝东风。","且共从容。","垂杨紫陌洛城东。","总是当时携手处，游遍芳丛。","聚散苦匆匆。","此恨无穷。","今年花胜去年红。","可惜明年花更好，知与谁同。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-176","tags":["宋词三百首"]},{"id":"poem-5cb9f040387cadc911cff0f2","title":"盘隠瘗猿","author":"释居简","dynasty":"宋","verses":["寸土如寸金，恩殊帷盖深。","病思罹穽日，死恨出林心。","残橡停朝赋，空樊绝夜吟。","六窗呼不应，云冷月沉沉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-89140748-b976-4c8f-8528-7ba25a4ab818","tags":[]},{"id":"poem-5cc8ed8f82ad8b4b33231a8e","title":"送张道士归山","author":"王维","dynasty":"唐","verses":["先生何处去，王屋访茅君。","别妇留丹诀，驱鸡入白云。","人间若剩住，天上复离群。","当作辽城鹤，仙歌使尔闻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-ae0f0690-88e2-4f08-8e30-ab9e370a1164","tags":[]},{"id":"poem-5cc919964b30e74dd5c42ef7","title":"咏史诗 章华台","author":"胡曾","dynasty":"唐","verses":["茫茫衰草没章华，因笑灵王昔好奢。","台土未干箫管绝，可怜身死野人家。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-ba01bb4b-8467-47d4-889a-052a319dfa36","tags":[]},{"id":"poem-5cd06b23586d43eff3ecb46b","title":"菩萨蛮·回文","author":"纳兰性德","dynasty":"清","verses":["雾窗寒对遥天暮，暮天遥对寒窗雾。","花落正啼鸦，鸦啼正落花。","袖罗垂影瘦，瘦影垂罗袖。","风翦一丝红，红丝一翦风。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-179","tags":[]},{"id":"poem-5cd117db12d872bd2ab77d4d","title":"奉和圣制送张说上集贤学士赐宴","author":"程行谌","dynasty":"唐","verses":["圣主崇文化，锵锵得盛才。","相因归梦立，殿以集贤开。","象系微言阐，诗书至道该。","尧尊承帝泽，禹膳自天来。","礼洽欢逾长，风恬暑更回。","国朝将舜颂，同是一康哉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-337e560d-f0eb-489f-8b80-4ecca434391a","tags":[]},{"id":"poem-5cdacc49f53592d752c6a95b","title":"白发","author":"张载","dynasty":"宋","verses":["白发千梳昼景暄，乌瓶一啜夜窗寒。","庙堂勤苦茅斋静，不见人心是两般。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-e0c79198-8c7e-4132-b971-86f4a923c690","tags":[]},{"id":"poem-5cdf26e088e9240f7019af32","title":"上达奚舍人","author":"孟郊","dynasty":"唐","verses":["北山少日月，草木苦风霜。","贫士在重坎，食梅有酸肠。","万俗皆走圆，一身犹学方。","常恐众毁至，春叶成秋黄。","大贤秉高鉴，公烛无私光。","暗室晓未及，幽行涕空行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-d975de03-a422-47c9-b4a1-30768576d816","tags":[]},{"id":"poem-5ce2ebbd33de80678ccd7b72","title":"宿灵泉寺二首  其一","author":"刘跂","dynasty":"宋","verses":["石磴排林端，路转阴岭滑。","侧身长风外，凛落天为阔。","冉冉光风浮，金轮起天末。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-b7262bea-ca50-4e53-9166-4dd958b2699b","tags":[]},{"id":"poem-5ce37b8f89e8c52d8bc37807","title":"阁夜","author":"杜甫","dynasty":"唐","verses":["岁暮阴阳催短景，天涯霜雪霁寒宵。","五更鼓角声悲壮，三峡星河影动摇。","野哭几家闻战伐，夷歌数处起渔樵。","卧龙跃马终黄土，人事依依漫寂寥。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-0f5874bf-3748-44c9-bc3a-be4a8c3eb2f6","tags":["唐诗三百首"]},{"id":"poem-5ce6e3b7b8f841c13737690a","title":"清平乐·角声哀咽","author":"纳兰性德","dynasty":"清","verses":["角声哀咽，襆被驮残月。","过去华年如电掣，禁得番番离别。","一鞭冲破黄埃乱山影里徘徊。","蓦忆去年今日，十三陵下归来。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-164","tags":[]},{"id":"poem-5ce85edc09cd98b362ad46c8","title":"泗上奉送相公","author":"赵嘏","dynasty":"唐","verses":["语堪铭座默含春，西汉公卿绝比伦。","今日抱辕留不得，欲挥双涕学舒人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-b88c0412-546b-454c-a373-d88b4da95816","tags":[]},{"id":"poem-5cfdf1ee271194cfdcc3e6fc","title":"无题四首 一","author":"李商隐","dynasty":"唐","verses":["来是空言去绝踪，月斜楼上五更钟。","梦为远别啼难唤，书被催成墨未浓。","蜡照半笼金翡翠，麝熏微度绣芙蓉。","刘郎已恨蓬山远，更隔蓬山一万重。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-7377e34a-1aab-47e3-a6dd-376c98a5d6b7","tags":["唐诗三百首","思念","记梦","七言律诗","爱情"]},{"id":"poem-5cffdc7fbea4faf820d50431","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["长安古道，盘费知多少。","婆婆早与，它便起程又早。","(旦)今朝倚靠，非外来相扰。","(合同前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2573","tags":[]},{"id":"poem-5d0441d46dc68ca706d2966b","title":"浣溪沙·江馆清秋缆客船","author":"薛昭蕴","dynasty":"五代","verses":["江馆清秋缆客船，故人相送夜开筵，麝烟兰焰簇花钿。","正是断魂迷楚雨，不堪离恨咽湘弦，月高霜白水连天。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-31","tags":[]},{"id":"poem-5d058c5fa50a9eee2dc4f34d","title":"滴翠峰","author":"陈岩","dynasty":"宋","verses":["春气薰空草木浮，绿云冉冉起山头。","岚光浥翠浓于染，润入衣襟冷欲秋。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-fa6511b0-26db-44ca-ab46-b2c08007e6f0","tags":[]},{"id":"poem-5d0c5022bb150e0c215f5996","title":"杨柳枝·根柢虽然傍浊河","author":"孙光宪","dynasty":"五代","verses":["根柢虽然傍浊河，无妨终日近笙歌。","骖骖金带谁堪比，还共黄莺不较多。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-43","tags":[]},{"id":"poem-5d10a93f3776d07993eb1a0c","title":"浣溪沙·酒醒香销愁不胜","author":"纳兰性德","dynasty":"清","verses":["酒醒香销愁不胜，如何更向落花行。","去年高摘斗径盈，夜雨几番销瘦了，繁华如梦总无凭。","人间何处问多情。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-137","tags":[]},{"id":"poem-5d2d1e7b70488a9118781187","title":"天边行","author":"杜甫","dynasty":"唐","verses":["天边老人归未得，日暮东临大江哭。","陇右河源不种田，胡骑羌兵入巴蜀。","洪涛滔天风拔木，前飞秃鹙后鸿鹄。","九度附书向洛阳，十年骨肉无消息。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-4b0bc117-6db3-4fe7-a7ac-6df03c52a62a","tags":["思乡","漂泊"]},{"id":"poem-5d2f73623263db4accf2335a","title":"三川观水涨二十韵","author":"杜甫","dynasty":"唐","verses":["我经华原来，不复见平陆。","北上唯土山，连山走穷谷。","火云无时出，飞电常在目。","自多穷岫雨，行潦相豗蹙。","蓊匌川气黄，群流会空曲。","清晨望高浪，忽谓阴崖踣。","恐泥窜蛟龙，登危聚麋鹿。","枯查卷拔树，礧磈共充塞。","声吹鬼神下，势阅人代速。","不有万穴归，何以尊四渎。","及观泉源涨，反惧江海覆。","漂沙坼岸去，漱壑松柏秃。","乘陵破山门，回斡裂地轴。","交洛赴洪河，及关岂信宿。","应沈数州没，如听万室哭。","秽浊殊未清，风涛怒犹蓄。","何时通舟车，阴气不黪黩。","浮生有荡汨，吾道正羁束。","人寰难容身，石壁滑侧足。","云雷此不已，艰险路更跼。","普天无川梁，欲济愿水缩。","因悲中林士，未脱众鱼腹。","举头向苍天，安得骑鸿鹄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-212bf433-f47a-4f05-84d1-172804896869","tags":[]},{"id":"poem-5d2fb2d1ed71cc2da9b07a6e","title":"蝶恋花·越女采莲秋水畔","author":"欧阳修","dynasty":"宋","verses":["越女采莲秋水畔。","窄袖轻罗，暗露双金钏。","照影摘花花似面。","芳心只共丝争乱。","㶉𫛶滩头风浪晚。","雾重烟轻，不见来时伴。","隐隐歌声归棹远。","离愁引著江南岸。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-636","tags":[]},{"id":"poem-5d3610e42922660ac4e96c75","title":"柳枝辞十二首  其四","author":"徐铉","dynasty":"宋","verses":["夹岸朱栏柳映楼，绿波平幔带花流。","歌声不出长条密，忽地风回见彩舟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-3aef44d7-2482-496e-aa68-bdaa6bbbc4de","tags":[]},{"id":"poem-5d3659207e5094467862be3b","title":"杏殇 二","author":"孟郊","dynasty":"唐","verses":["地上空拾星，枝上不见花。","哀哀孤老人，戚戚无子家。","岂若没水凫，不如拾巢鸦。","浪鷇破便飞，风雏褭相夸。","芳婴不复生，向物空悲嗟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-cd91cd6c-166f-4f90-bcab-d71b2f6d48bc","tags":[]},{"id":"poem-5d3c56569e83e70dfe362741","title":"燕子龛禅师","author":"王维","dynasty":"唐","verses":["山中燕子龛，路剧羊肠恶。","裂地竞盘屈，插天多峭崿。","瀑泉吼而喷，怪石看欲落。","伯禹访未知，五丁愁不凿。","上人无生缘，生长居紫阁。","六时自搥磬，一饮常带索。","种田烧白云，斫漆响丹壑。","行随拾栗猿，归对巢松鹤。","时许山神请，偶逢洞仙博。","救世多慈悲，即心无行作。","周商倦积阻，蜀物多淹泊。","岩腹乍旁穿，涧唇时外拓。","桥因倒树架，栅值垂藤缚。","鸟道悉已平，龙宫为之涸。","跳波谁揭厉，绝壁免扪摸。","山木日阴阴，结跏归旧林。","一向石门里，任君春草深。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-5233e44e-9520-4bf7-aaca-3b3a74dfe81e","tags":[]},{"id":"poem-5d43d01757f24c10c73541f3","title":"宣义池上","author":"刘得仁","dynasty":"唐","verses":["修篁夹绿池，幽絮此中飞。","何必青山远，仍将白发归。","鸟啼亦有恨，鸥习总无机。","树起秋风细，西林磬入微。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-78ada3c5-92a7-4de7-ae14-836488679e66","tags":[]},{"id":"poem-5d494d1cea334629f1164b16","title":"和丘员外题湛长史旧居","author":"于𬱖","dynasty":"唐","verses":["萧条历山下，水木无氛滓。","王门结长裾，岩扃怡暮齿。","昔贤枕高躅，今彦仰知止。","依依瞩烟霞，眷眷返墟里。","湛生久已没，丘也亦同耻。","立言咸不朽，何必在青史。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-549fb397-6297-4c75-bbe0-f9bace405b5d","tags":[]},{"id":"poem-5d5c1de0171fc0906e2ae40f","title":"虞美人·翠屏闲掩垂珠箔","author":"顾敻","dynasty":"五代","verses":["翠屏闲掩垂珠箔，丝雨笼池阁。","露沾红藕咽清香，谢娘娇极不成狂，罢朝妆。","小金㶉𫛶沉烟细，腻枕堆云髻。","浅眉微敛注檀轻，旧欢时有梦魂惊，悔多情。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-35","tags":[]},{"id":"poem-5d5fafad49fb362385704cb7","title":"献题金鳌山","author":"吕从庆","dynasty":"唐","verses":["金鳌腾腾高百丈，昔者曾游东海浪。","女娲断足奠坤舆，怒身化作安吴嶂。","骨肉虽变魂魄鲜，千秋万古生云烟。","闲花老树满馥郁，飞走异类争蹁跹。","草堂熟对忽诧异，念在神僊广游戏。","琴高跨鲤如跨驴，初成乘龙较容易。","我今自号钓鱼郎，丝纶倍比任公长。","愿言活汝骑脚底，御风直造星辰傍。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-d42000d1-fe4b-43dd-b6e0-90287c7b8978","tags":[]},{"id":"poem-5d62c4e55d316343826ae8d1","title":"天保","author":"佚名","dynasty":"先秦","verses":["天保定尔，亦孔之固。俾尔单厚，何福不除？俾尔多益，以莫不庶。","天保定尔，俾尔戬谷。罄无不宜，受天百禄。降尔遐福，维日不足。","天保定尔，以莫不兴。如山如阜，如冈如陵，如川之方至，以莫不增。","吉蠲为饎，是用孝享。禴祠烝尝，于公先王。君曰：卜尔，万寿无疆。","神之吊矣，诒尔多福。民之质矣，日用饮食。群黎百姓，遍为尔德。","如月之恒，如日之升。如南山之寿，不骞不崩。如松柏之茂，无不尔或承。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-165","tags":[]},{"id":"poem-5d6e396952b8bf5b9131ba28","title":"送人归湖南","author":"释了惠","dynasty":"宋","verses":["白纸无端墨笔书，分明一句却模糊。","青灯夜雨湘江上，添得平沙落雁图。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-cb7f0628-c8c5-4a70-84cd-6a38f01ef527","tags":[]},{"id":"poem-5d7ba6ce688e9feb585034ad","title":"麦穗两岐","author":"郑畋","dynasty":"唐","verses":["圣虑忧千亩，嘉苗荐两岐。","如云方表盛，成穗忽标奇。","瑞露纵横滴，祥风左右吹。","讴歌连上苑，化日遍平陂。","史册书堪重，丹青画更宜。","愿依连理树，俱作万年枝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-1567757f-34ad-40e6-8bf2-d2eb76454a2c","tags":[]}];
